programs.sol:
"""Mostly a negative detector for written 'pop' and its word family.

Bare pop (especially the .pop method) is strongest; popular/population
and inflections are weaker. Smaller responses cover push/pod, Cyrillic
lookalikes, and listed words for popping, crowds, or popularity in CJK.
A word ending split after pop, and 'population of', retain a response.
Only the previous token is remembered; document changes clear it.
Weak background activations and finer contextual variation are omitted.
"""
READS = ()
LEADING = ' \t\r\n._(/-'


def response(token):
    word = token.lstrip(LEADING).lower()
    if word == 'pop':
        if token.lstrip().startswith('.pop'):
            return -7.2
        if token.lstrip().startswith('-') or token.strip() == 'POP':
            return -4.8
        return -6.0
    if word in {'popular', 'population', 'populations', 'popul'}:
        return -4.2
    if word in {'pops', 'popped', 'popping'}:
        return -4.0
    if word in {'popularity', 'populate', 'popup'}:
        return -3.0
    if word in {'populace', 'populous', 'popover', 'popmatrix'}:
        return -2.5
    if word in {'populated', 'unpopular', 'população', 'población', 'pobl'}:
        return -1.9
    if word in {'popcorn', 'popen'}:
        return -1.0
    if word.startswith('популяр'):
        return -2.7
    if word == 'попу':
        return -3.3
    if word == 'поп':
        return -2.1
    if word == 'под':
        return -1.1
    if word in {'pod', 'pods'}:
        return -0.7
    if word in {'push', 'pushes', 'pushed', 'pushing'}:
        return -1.1 if token.lstrip().startswith('.') else -0.8
    if word in {'prominent', 'prevalent', 'trending'}:
        return -0.8
    # Spring, bounce, or bullet; the same character in three writing systems.
    if word in {'弹', '彈', '弾'}:
        return -4.3 if word == '弹' else -3.4
    # Popular, fashionable, populous, or crowded.
    if word == '流行':
        return -3.4
    if word in {'热门', '熱門'}:
        return -2.9
    if word in {'人口', '盛行', '流行的'}:
        return -2.1
    if word in {'推', '人气', '人氣', '人群', '群体', '群體'}:
        return -1.3
    if word.startswith(('推出', '推薦')):
        return -1.0
    # Coming out, bursting, bubbling, jumping, or a crowd.
    if word == '出':
        return -0.3
    if word in {'爆', '泡', '跳', '蹦', '破', '众', '眾', '大众', '大眾'}:
        return -0.8
    if word.startswith(('出来', '出來')):
        return -0.7
    return 0.002


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == document
    previous = carry[1] if same_document else ''
    # Recover a completed character when a token is just its final UTF-8 bytes.
    if same_document and '\ufffd' in token:
        completed = prefix.text_prefixes[-1][-1:]
        if completed in {'弹', '彈', '弾'}:
            token = completed
    word = token.lstrip(LEADING).lower()
    value = response(token)
    if word == 'of' and previous in {'population', 'populations'}:
        value = -1.9
    elif word == 'of' and previous in {'popularity', 'popular'}:
        value = -1.2
    elif previous in {'pop', 'popul'} and not token[:1].isspace():
        if word.startswith(('ul', 'ol')):
            value = -2.0
    elif previous in {'弹', '彈', '弾'} and word == '出':
        value = -3.2
    return (document, word), value

programs.luna:
"""A sparse lexical cue: pop words are strongest, with smaller push/pod cues."""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()

    if word.startswith(("pop", "поп")):
        return None, -5.5 if word in {"pop", "pops"} else -4.0
    if word.startswith("push"):
        return None, -0.8
    if word.startswith("pod") or word == "под":
        return None, -1.0
    return None, 0.0

programs.sol:
"""A mostly lexical detector of noun-specifying words.

Near demonstratives ('this', 'these') dominate, followed by 'each', 'those',
'another', 'every', and 'our'. Some temporal/prominence modifiers respond
more weakly. Recognize common translated forms too. Case and token boundaries
change the strength. Ignore Latin-alphabet suffixes of an earlier token, and
allow punctuation around a complete word. Carry resets at document boundaries.
"""
READS = ()

ENGLISH = {
    'each': 1.17,
    'those': 0.76,
    'another': 0.79,
    'every': 0.60,
    'our': 0.50,
    'other': 0.23,
    'former': 0.53,
    'main': 0.47,
    'future': 0.41,
    'little': 0.23,
    'next': 0.17,
    'latter': 0.23,
}

# Demonstratives, distributive determiners, and first-person plural forms.
GERMAN_NEAR = set('diese dieser dieses diesen diesem'.split())
ROMANCE_DETERMINERS = set(
    'cette chaque cada este esta estos estas questo questa'.split()
)
RUSSIAN_NEAR = set('этот эта эти этом этого эту этой этих'.split())
CHINESE_DETERMINERS = {
    '这': 0.33, '这个': 0.33,
    '這': 0.41, '這個': 0.41,
    '这些': 0.53, '這些': 0.53,
    '此': 0.68, '那': 0.27, '那些': 0.41,
    '各': 0.66, '每个': 0.56,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().strip("\"'“”()[]<>.,/")
    lower = word.lower()
    spaced = bool(token[:1].isspace())
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    state = (doc, token)
    # An unspaced Latin-alphabet suffix is not a separate determiner.
    if (token[:1].isascii() and token[:1].isalpha()
            and previous[-1:].isalpha()):
        return state, 0.0
    if lower in {'this', 'these'}:
        if word.isupper():
            value = 1.30
        elif word[:1].isupper():
            value = 0.99 if spaced else 1.17
        else:
            value = 1.44 if spaced else 1.18
            if token.startswith('('):
                value = 0.92
    elif lower in ENGLISH:
        value = ENGLISH[lower]
        if lower == 'each' and word[:1].isupper():
            value = 1.03
        elif lower == 'those' and word[:1].isupper():
            value = 0.63
        if not spaced and word.islower():
            if lower in {'our', 'former'}:
                value = 0.05
            elif lower == 'each':
                value = 0.89
            elif lower == 'main':
                value = 0.36
    elif lower in GERMAN_NEAR:
        value = 0.82
    elif lower in ROMANCE_DETERMINERS:
        value = 0.73
    elif lower in RUSSIAN_NEAR:
        value = 0.62
    elif spaced and lower in {'ce', 'ces'}:
        value = 0.31
    elif word == 'この':
        value = 1.12
    elif word == 'これ':
        value = 0.48
    elif word in CHINESE_DETERMINERS:
        value = CHINESE_DETERMINERS[word]
    elif word in {'我们', '我們', '我们的', '我們的'}:
        value = 0.55
    elif lower in {'unsere', 'наш', 'наша', 'наши'}:
        value = 0.47
    elif word in {'هذا', 'هذه'}:
        value = 0.55
    else:
        value = 0.0
    return state, float(value)

