READS = ()

MAKE = {" make", " makes", " made", " making"}
def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if tok in (" sense", " sure") and prev in MAKE:
        return None, 0.25
    if tok == " to" and prev == " designed":
        return None, 0.2
    if tok == " from":
        return None, -0.03
    if tok == "erv":
        return None, -0.2
    return None, 0.0

programs.luna:
"""Catch a sparse positive pulse around the English word 'sense'."""

READS = ()


def step(carry, prefix, upstream):
    """Predict +1 for ' sense' near make/makes/get/gets in the same document."""
    t = prefix.position
    if prefix.token_strings[t] != " sense":
        return None, 0.0

    doc = prefix.document_ids[t]
    for i in range(t - 1, max(-1, t - 5), -1):
        if prefix.document_ids[i] != doc:
            break
        word = prefix.token_strings[i].strip().lower()
        if word in {"make", "makes", "get", "gets"}:
            return None, 1.0
    return None, 0.0

programs.sol:
"""Negative lexical pulses for proof, evidence, verification and assurance.

Proof and its East Asian counterparts are strongest. Witnesses, certificates
and verification are intermediate; showing and guaranteeing are weaker.
Remember one spelling fragment and semantic family to handle split words and
phrases such as 'proof of' and 'show that'. Other tokens predict zero. These are spelling rules, not judgments about
whether a claim is true: code identifiers and incidental fragments can fire too.
"""
import re

READS = ()
FAMILIES = (
    ('proof', r'^proof', -5.1),
    ('prove', r'^(dis)?(prove|proved|proves|proven|proving|provable)$', -2.9),
    ('witness', r'^witness(es|ed|ing)?$', -2.1),
    ('verify', r'^verif(y|ied|ies|ying|ication|ications|ier|iable)$', -1.85),
    ('certificate', r'^certificates?$', -2.6),
    ('certify', r'^certif(y|ied|ies|ying|ication|ications)$', -1.7),
    ('certify', r'^certs?$', -1.3),
    ('evidence', r'^(evidence|evidenced|evid)$', -1.5),
    ('evidence', r'^(corrobor|substant|attest)', -1.0),
    ('auth', r'^auth(entic.*)?$', -1.0),
    ('validate', r'^validat(e|ed|es|ing|ion|ions|or|ors)$', -1.25),
    ('confirm', r'^confirm', -1.0),
    ('testimony', r'^(testif|testimon)', -1.2),
    ('demonstrate', r'^demonstrat', -0.9),
    ('ensure', r'^(ensur|guarantee|garant|guar$)', -0.85),
    ('assure', r'^(assur|justif)', -0.6),
    ('argument', r'^(argument|argue|arguing)', -0.65),
    ('contradict', r'^contrad', -0.45),
    ('credentials', r'^(credentials?|ssl|receipts?|passport|warranty|vouchers?)$', -0.85),
    ('audience', r'^(audience|spectators?)$', -0.75),
    ('doubt', r'^doubt', -0.55),
    ('documents', r'^(documents?|manuscripts?|affidavit|audit)', -0.4),
    ('quantify', r'^(quant$|quantitativ|quantif|quantiz)', -0.7),
    ('show', r'^(show|shown|showed|shows|showing)$', -0.16),
)
FAMILIES = tuple((name, re.compile(pattern), value)
                 for name, pattern, value in FAMILIES)
# Selected proof, certification, guarantee and identification translations.
TRANSLATED_TERMS = {
    '证': -7.7, '證': -6.8, '証': -7.5, '증': -5.1,
    '证明': -4.9, '證明': -4.6, '证书': -4.0, '证实': -3.5,
    '验证': -3.2, '认证': -3.3, '证据': -2.3, '见证': -3.5,
    '证件': -2.6, '考证': -2.9, '公证': -3.8, '论证': -4.3,
    '证券': -1.1, '身份证': -1.3, '凭证': -1.7, '许可证': -1.5,
    '保证': -1.2, '保證': -1.2, '保障': -0.7, '确保': -0.7,
    '确认': -0.7, '確認': -0.7, '鉴定': -0.7, '认定': -0.6,
    '保': -0.8, '观众': -0.9, '取证': -4.6, '辩证': -2.6,
    '担保': -1.7, '核实': -1.1, '检验': -0.75, '凭': -0.65,
    '签证': -1.9, '通行证': -1.7, 'chứng': -5.5,
}
ENDINGS = {'s', 'es', 'ed', 'ing', 'ies', 'ance', 'ence', 'ates', 'ating',
           'ion', 'ation', 'ations', 'ify', 'ifies', 'ified', 'ifying',
           'ifiable', 'ification', 'ifications'}
# Incomplete UTF-8 tokens: E8 A8 (Japanese speech-radical characters including
# 証), and 20 EC A6 (space + Korean syllables around 증).
JAPANESE_SPEECH_PREFIX = 28145
KOREAN_EVIDENCE_PREFIX = 132376


def lexical(word, raw):
    for name, pattern, value in FAMILIES:
        if pattern.match(word):
            if word == 'proofs':
                value = -3.7
            elif raw == 'proof':
                value = -4.1
            elif name == 'prove':
                value = {'proved': -2.2, 'proven': -1.5,
                         'proves': -2.45, 'provable': -0.6}.get(word, value)
            elif word == 'verify':
                value = -2.05 if raw.startswith(' ') and raw.islower() else -1.65
            elif word == 'auth' and raw[:1] in '._':
                value = -1.5
            elif word == 'arguments' and not raw.startswith(' '):
                value = 0.0
            return name, value
    return '', 0.0


def following(word, family, previous_word):
    if word == 'of':
        if family == 'proof':
            return -2.6 if previous_word == 'proofs' else -4.3
        if family in {'evidence', 'certificate', 'verify', 'argument', 'testimony'}:
            return -1.1
    if word == 'that':
        if family in {'proof', 'prove'}:
            return -1.0
        if family in {'verify', 'evidence', 'show', 'demonstrate'}:
            return -0.47 if previous_word == 'shown' else -0.65
    if word in {'the', 'this', 'how'}:
        if family in {'prove', 'verify', 'demonstrate'}:
            return -0.7
        if family == 'show':
            return -0.4 if word == 'how' else -0.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    _, tail, previous = carry if carry and carry[0] == doc else (doc, '', '')
    raw = prefix.token_strings[-1]
    word = raw.strip(' \t\r\n._/-()[]{}:;,').lower()
    joined = tail + word if raw[:1].isalpha() and tail else word
    name, value = lexical(word, raw)
    if word == 'prove' and tail.endswith('im'):
        name, value = '', -0.35
    if not name and joined != word and (len(tail) <= 5 or word in ENDINGS):
        name, value = lexical(joined, ' ' + joined)
        if name == 'proof' and word in {'of', 'ofs'}:
            value = -2.5 if word == 'of' else -6.0
        elif name == 'certificate':
            value = -3.5 if raw == 'IFICATE' else -2.1
        elif name == previous and word in ENDINGS:
            if word in {'s', 'es', 'ed', 'ing', 'ies', 'ance', 'ence', 'ion'}:
                value *= 0.4
        elif name == previous or raw.isupper() or joined == 'evid':
            name, value = '', 0.0
    if raw[:1].isspace() or raw[:1] == '-':
        value += following(word, previous, tail)
        if previous == 'proof' and raw in {'-of', ' OF'}:
            value = -5.3 if raw == '-of' else -0.9
    text = prefix.text_prefixes[-1][-4:] if '\ufffd' in raw else raw.strip()
    if raw.strip() in TRANSLATED_TERMS:
        value = TRANSLATED_TERMS[raw.strip()]
        name = 'proof' if text in {'证明', '證明'} else 'cjk'
    elif '\ufffd' in raw and text[-1:] in TRANSLATED_TERMS:
        value, name = TRANSLATED_TERMS[text[-1]], 'proof_character'
    if raw in {'证', '證', '証'}:
        before = prefix.text_prefixes[-1][-4:]
        if before.endswith(('验证', '驗證')):
            value = -3.2
        elif before.endswith(('认证', '認證')):
            value = -5.6
        name = 'proof_character'
    if raw == '明' and previous == 'proof_character':
        name, value = 'proof', -1.9
    if raw == '了' and previous == 'proof':
        value = -3.0
    token = prefix.token_ids[-1]
    if token == JAPANESE_SPEECH_PREFIX:
        value = -3.5
    elif token == KOREAN_EVIDENCE_PREFIX:
        value = -4.4
    tail = joined[-24:] if raw[-1:].isalpha() else ''
    if '\ufffd' in raw and text[-1:].isalpha():
        tail = text[-1]
    return (doc, tail, name), float(value)

programs.luna:
"""Recognize language about evidence, proof, and verification.

It marks those words and related terms for showing or assuring a result.
A few following words (such as 'that') get a smaller mark immediately
after a cue. Word fragments are joined until a word boundary.
"""

READS = ()

# Specific evidence and checking words, plus direct equivalents in Chinese,
# Japanese, and Korean.
STRONG = (
    "proof", "prove", "verif", "certif", "credential", "authenticat",
    "evidence", "evidenc", "testimon", "witness", "attest", "corroborat",
    "validat", "身份证", "考证", "证据", "证明", "验证", "认证", "鉴定",
    "證", "證據", "認証", "証明", "증명",
)
SUPPORT = (
    "show", "demonstrat", "ensure", "guarante", "confirm", "assur",
    "establish", "justify", "contradict", "illustrat", "warrant",
    "保证", "保障", "确保", "确认", "証拠", "確認", "확인",
)
FOLLOW = {"that", "this", "which", "to", "by", "of", "for"}


def _kind(word):
    if any(root in word for root in STRONG):
        return 2
    if any(root in word for root in SUPPORT):
        return 1
    return 0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, marked, previous_kind = "", False, 0
    else:
        _, word, marked, previous_kind = carry

    hit = 0
    followed = False
    piece = prefix.token_strings[-1].lower()
    for char in piece:
        if char.isalpha() or char.isdigit():
            word += char
            if previous_kind and word in FOLLOW:
                followed = True
                previous_kind = 0
            elif previous_kind and not any(w.startswith(word) for w in FOLLOW):
                previous_kind = 0
            if not marked:
                hit = max(hit, _kind(word))
                marked = bool(hit)
        else:
            if word:
                previous_kind = _kind(word)
            word, marked = "", False

    value = -1.05 if hit == 2 else (-0.20 if hit == 1 else (-0.35 if followed else 0.0))
    return (doc, word, marked, previous_kind), float(value)

programs.sol:
"""A negative lexical response to words for numbers, symbols and signals.

This detects the words, not digits. Chinese 号/號 (number/designation) and
Korean 호 are especially strong triggers. Separate strengths distinguish
plurals, derived forms and identifier spellings. Other tokens stay near zero.
It uses only the current token, so no state can leak between documents.
"""
READS = ()
NUMBER_WORDS = {'numero', 'número', 'nummer', 'номер'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.strip('_().<>[-').lower()
    value = -0.001

    if text in {'号', '號'}:
        value = -6.6
    elif '号' in text or '號' in text:
        value = -2.2
    elif text == '호':
        value = -3.2 if token == text else -3.9
    elif text == '№':
        value = -2.25
    elif word == 'number':
        value = -1.38
        if text.startswith(('_', '.', '(')):
            value = -1.0
        elif text.startswith(('<', '[')):
            value = -0.75
    elif word in {'numbers', 'numbered', 'numbering'}:
        value = -1.0
    elif word in NUMBER_WORDS:
        value = -1.45 if word == 'номер' else -0.83
    elif word in {'signal', 'signals'}:
        value = -2.18 if word == 'signal' else -2.09
        if text.isupper() or text.startswith(('_', '(')) or token == 'signal':
            value = -1.6
    elif word in {'signaling', 'signalling', 'signaled', 'signalled'}:
        value = -1.0
    elif word in {'symbol', 'symbols'}:
        value = -1.0
        if text == 'symbol' and token.startswith(' '):
            value = -1.35
        elif token == 'symbol':
            value = -0.2
    return None, value

programs.haiku:
"""layers.0.mlp.down_proj:3590 -- a "number / signal / symbol" word detector.

This component is almost silent everywhere. It goes strongly negative on the token
that names a number or a signal/symbol, and most strongly on the CJK character 号
(also 號), the "number / No." sign used in Chinese (e.g. 163号, 账号, 号码).
Activations are negative, so the prediction is a negative size per token:

  号, 號                 about -6   (Chinese "number" sign; strongest)
  signal-type words      about -2   (" signal", " signals", "signaling")
  number words           about -1.4 (" number", "Number", "numero", "номер", "№")
  " numbers"             about -1.0
  symbol-type words      about -1.2 (" symbol", " symbols")
  other CJK ...号/...號  about -3   (e.g. 信号, 微信号)
  호 (Korean)            about -3

Every other token predicts 0. The component carries no state: it reads only the
newest token. A token-identity table like this explains about 40% of its variance;
the remainder is small noise spread over many tokens.
"""

READS = ()

SIGN_CHARS = {"号": -6.0, "號": -6.0, "호": -3.0}
NUMBER_WORDS = {
    "number": -1.3, "numbers": -1.0, "numero": -1.3, "número": -1.3,
    "номер": -1.3, "№": -1.3,
}
SIGNAL_WORDS = {"signal": -2.0, "signals": -2.0, "signaling": -2.0, "signalling": -2.0}
SYMBOL_WORDS = {"symbol": -1.2, "symbols": -1.2}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = s.strip().lower()
    if s in SIGN_CHARS:
        return None, SIGN_CHARS[s]
    if "号" in s or "號" in s:
        return None, -3.0
    for table in (NUMBER_WORDS, SIGNAL_WORDS, SYMBOL_WORDS):
        if w in table:
            return None, table[w]
    return None, 0.0

programs.luna:
"""Approximate the component with a small response on the token 'to'.

Harvested high-impact examples repeatedly place this word at the current
position; other tokens receive no response in this simple approximation.
"""
READS = ()

TO_TOKENS = {' to', ' To', 'To', ' TO'}


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] in TO_TOKENS:
        return None, -0.45
    return None, 0.0

"""Predicts the negative response concentrated on Cyrillic word pieces, especially capitals."""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    letters = [
        ch for ch in token
        if ch.isalpha() and "CYRILLIC" in unicodedata.name(ch, "")
    ]
    if not letters:
        return None, 0.0
    value = -1.05 if any(ch.isupper() for ch in letters) else -0.55
    return None, float(value)

programs.sol:
"""A written 'mo' syllable detector.

Bare mo syllables have large negative activations; longer fragments have
smaller ones. The same pattern extends to Japanese/Korean mo and selected
Chinese mo/mu characters. Common complete mo-words are mostly quiet.
This is a spelling-based approximation, not a general meaning detector.
"""
READS = ()

QUIET_WORDS = {
    'more', 'most', 'money', 'modern', 'memory', 'memories', 'morning',
    'move', 'moved', 'moving', 'movement', 'mostly',
}
CHINESE_MO_MU = set('模莫摩摸募')


def response(token):
    bare = token.strip()
    word = bare.lstrip('._/-(')
    w = word.lower()
    if word in {'モ', '모', 'โม'}:
        return -4.0
    if word.endswith('も'):
        return -1.0 if word in {'も', 'でも', 'にも', 'のも', 'かも'} else -0.5
    if len(word) == 1 and word in CHINESE_MO_MU:
        return -3.0
    if any(c in CHINESE_MO_MU for c in word):
        return -0.6
    if w in {'мо', 'مو', 'mö', 'mô', 'mó'}:
        return -1.1
    if w == 'mo':
        return -3.1
    if w in QUIET_WORDS or w.startswith(('model', 'modif')):
        return 0.0

    # Open syllables and common Latin endings.
    if w in {'emo', 'memo'}:
        return -3.45 if w == 'emo' else -2.4
    if w in {'amo', 'imo'} and not token[:1].isspace():
        return -2.1
    if w == 'omo':
        return -1.8
    if w in {'demo', 'ermo', 'umo', 'amos', 'imos', 'emos', 'amus', 'imus'}:
        return -1.0

    # Longer word families retain a smaller part of the response.
    if w.startswith(('module', 'modular', 'modulo', 'modulus')):
        return -0.87
    if w == 'mod':
        return -0.7 if bare.startswith('.') else -0.13
    if w.startswith(('moist', 'moor', 'mood')):
        return -1.2
    if w.startswith(('memor', 'memoir')):
        return -1.0
    if w.startswith(('emot', 'emoc', 'atmos', 'omorph')):
        return -0.6
    if w.startswith('molecul'):
        return -0.8 if w.endswith('ar') else -0.26
    if w.startswith('mo'):
        if len(w) == 3:
            return {'mon': -0.7, 'mor': -1.1, 'mos': -1.35}.get(w, -0.8)
        if w.startswith(('mont', 'mort', 'modo', 'mock')):
            return -0.2
        return -0.5 if len(w) == 4 else -0.3
    return 0.0


def step(carry, prefix, upstream):
    return None, float(response(prefix.token_strings[-1]))

"""A lexical detector for systems, their users, and computing tools.

Predict positive responses for system/user words, operating systems, tools,
languages, and software-agent nouns, including recognizable subword stems.
Use a few case and code-separator distinctions. Chat roles differ from user
mentions. Join Node.js and Windows Server across tokens; boost development
environments and `running on` / `hosted on`. Small file/storage/bug and
chat-delimiter corrections supplement a zero background. These rules capture
one lexical family, not every token-specific or contextual effect.
"""
READS = ()

SYSTEMS = set('system systems ystem ystems 系统 系統'.split())
USERS = set('user users 用户 用戶'.split())
LINUX = set('linux inux ubuntu debian fedora'.split())
TOOLS = set('tool tools editor validator interpreter toolbox toolkit 工具'.split())
LANGUAGES = set('python java ruby uby perl php matlab golang olang conda'.split())
AGENTS = set('manager builder loader renderer formatter emulator parser reader '
             'writer generator solver listener runner helper setter getter '
             'compiler scanner recorder finder checker tester tokenizer '
             'optimizer executor exporter trainer binder wrapper controller '
             'router'.split())
COMPUTING = set('environment environments server servers machine machines '
                'desktop laptop workstation 机 機'.split())
TRANSLATED_SYSTEMS = set('sistema sistemas système систем система системы システム'.split())
TAGS = {'</tool_response>': -0.14, '<tool_response>': 0.09,
        '<|im_end|>': 0.05, '<think>': 0.12}


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lstrip('_-/.(').lower()
    value = 0.0
    if word in SYSTEMS:
        value = 0.68
    elif word in USERS:
        value = 0.56 if word == 'users' else 0.71
    elif word in LINUX:
        value = 0.77
    elif word in TOOLS:
        value = 0.55
    elif token in {' IDE', ' Explorer', ' IntelliJ', ' JDK'}:
        value = 0.80
    elif word in {'windows', 'unix', 'macos'}:
        value = 0.44 if word != 'windows' or text.startswith('W') else 0.06
    elif word in LANGUAGES or word in COMPUTING or word in TRANSLATED_SYSTEMS:
        value = 0.35
    elif word == 'manager':
        value = 0.95 if text.startswith('-') else (
            0.58 if token == 'Manager' else 0.32)
    elif word in AGENTS:
        value = 0.32
    elif word in {'client', 'clients'}:
        value = 0.16
    elif token == ' OS':
        value = 0.32
    elif word in {'cli', 'utils'}:
        value = 0.55 if word == 'cli' else 0.25
    elif text in {'.js', '.py', '.yaml', '.yml', '.go'}:
        value = {'.js': 0.31, '.py': 0.10, '.yaml': 0.20,
                 '.yml': 0.20, '.go': -0.13}[text]
    elif token in TAGS:
        value = TAGS[token]
    elif word in {'file', 'files', 'storage', 'service', 'services', 'connection'}:
        value = -0.10
    elif word in {'bug', 'bugs'}:
        value = -0.28

    prior = previous.strip().lower()
    if word in {'environment', 'environments'} and prior in {
        'development', 'developer', 'virtual', 'programming', 'runtime'
    }:
        value = 0.95
    elif word == 'on' and prior in {'running', 'hosted'}:
        value = 0.32
    elif word == 'js' and prior == 'node':
        value = 0.99
    elif word == 'server' and previous.strip() == 'Windows':
        value = 1.55
    elif previous == '<|im_start|>':
        if token in {'user', 'system'}:
            value = 0.02
        elif token == 'assistant':
            value = -0.06
    return (doc, token), value

