"""Layer-0 MLP down_proj component 3596: a word-level lexicon of the food-and-farming domain.

What it does: it looks only at the newest token, whole-word, case-insensitively.
  * Farming, agriculture and livestock words (agriculture, farm, crop, animal, vegetable, ...)
    push the activation negative.
  * Food, eating and nutrition words (food, sugar, healthy, eat, milk, ...) push it
    weakly negative.
  * Cooking and baking words (cook, bake, flour, bread, soup, recipe, ...) push it positive.
Chinese words for crops, animals, milk, eggs, food and eating are grouped in the same way.
Every other token predicts 0. The values are the average activations of these word groups
in training text; the sizes are rounded.
"""

READS = ()

AGRICULTURE = {
    "agriculture", "agricultural", "farm", "farming", "farmer", "farms", "crop", "crops",
    "harvest", "cultivate", "livestock", "fertilizer", "vegetable", "vegetables", "animal",
    "animals", "acres", "dairy", "vegan", "planting",
}
FOOD = {
    "food", "foods", "sugar", "salt", "healthy", "nutrition", "nutritional", "eat", "eating",
    "eaten", "tablespoons", "canned", "grocery", "organic", "milk", "egg", "eggs", "cake",
    "rice", "kitchen", "alcohol",
}
COOKING = {
    "cook", "cooker", "cooking", "cooked", "bake", "baking", "baked", "flour", "bread", "bean",
    "beans", "flavor", "soup", "chicken", "garlic", "potato", "cream", "soda", "cider",
    "recipe", "juice", "oven",
}


# Chinese words for crops, plants, animals, milk, eggs, salt, food and eating; mostly negative.
FARM_FOOD_CJK = {
    "农", "農", "種", "种", "植物", "培", "乳", "奶", "蛋", "盐", "菜", "动物", "食用", "美食",
    "浇水", "狗",
}
EATING_CJK = {"味", "茶", "葡萄酒", "吃", "喝", "食べ"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in AGRICULTURE or word in FARM_FOOD_CJK:
        return None, -0.2
    if word in FOOD or word in EATING_CJK:
        return None, -0.12
    if word in COOKING:
