programs.sol:
"""Estimate a content-separator signal from text.
Stops, commas, line breaks, 'and', and code separators are strongest early
in a document. Numbers, initials and introductory words weaken boundaries;
month names strengthen date-separating spaces. Ordinary words are near zero,
except opening articles, pronouns, imports, title labels and Markdown headings.
The state is just document identity, age in tokens, and the previous token.
"""
READS = ()
DISCOURSE = set('''however therefore thus so wait yes no now then first second
third finally moreover furthermore alternatively well hmm okay ok indeed also
instead nevertheless nonetheless likewise meanwhile hence otherwise similarly
consequently actually fortunately unfortunately perhaps certainly sure note
anyway next additionally'''.split())
MONTHS = set('''january february march april may june july august september
october november december jan feb mar apr jun jul aug sep sept oct nov dec'''.split())
FUNCTION_WORDS = set('''a an the and or but of in on at by to from for with as is
are was were be been being this that these those it its my your their our his
her some any each every no not if which who what when where'''.split())
ABBREVIATIONS = set('''mr mrs ms dr prof jr sr no fig figs eq eqs v vol pp p st
co inc ltd etc vs e.g i.e'''.split())


def boundary(s):
    """Return a baseline and an early-document boost, in familiar categories."""
    body = s.strip()
    blank = s.count('\n') > 1
    if s == ' and':
        return 'and', .70, 1.4
    if s == ' ':
        return 'space', .20, 1.8
    if s.isspace():
        if '\n' not in s or '\t' in s or len(s.split('\n')[0]) > 2:
            return 'indent', 0.0, 1.1
        if s.startswith(' '):
            return 'block', .85 if blank else .72, 3.0
        return 'newline', 1.1, 4.7 if blank else 6.6
    if s.startswith('<|') or s.startswith('<tool') or s.startswith('</tool'):
        return 'markup', -.15, 0.0
    if not body or any(c.isalnum() for c in s):
        return 'word', 0.0, 0.0
    if body in {'.', '?', '!', '。', '？', '！'}:
        if s.startswith(' '):
            return 'stop', .72, 1.4
        return 'stop', 1.35 if body in '。？！' else 1.24, 5.3
    if body in {',', '，', '،', '、'}:
        if s.startswith(' '):
            return 'comma', .01, 1.3
        if body == '、':
            return 'comma', .65, 1.5
        return 'comma', 1.08 if body in '，،' else .85, 3.0
    if body in {':', ';', '：', '；'}:
        if '\n' in s:
            return 'break', 1.6 if body == ';' and blank else .93, 3.8
        return 'colon', .62 if s.startswith(' ') else .81, 2.6
    if body in {'=', '==', '===', '!=', '<=', '>=', ':='}:
        return 'equals', .90 if s.startswith(' ') else .44, 1.8
    if body in {'<', '->', '—', '|'}:
        level = (.28 if body == '|' else .65) if s.startswith(' ') else .35
        return 'operator', level, 1.5
    if '\n' in s:
        if body.endswith('{'):
            return 'block', 2.0 if blank else 1.25, 2.4
        if body.endswith('}'):
            return 'block', 1.1 if blank else .35, 2.0
        return 'break', 1.1 if blank else .5, 3.4
    if body in {'..', '...', '…'}:
        return 'stop', .86, .9
    if body[0] in '\"\'' and body[-1] in ',:':
        return 'colon', .72, 1.9
    if any(c in '.。！？' for c in body) and all(c in '.!?。！？\"\'”’)]}' for c in body):
        return 'stop', .62, 3.2
    if body == ')':
        return 'paren', -.06, 2.6
    if set(body) == {'#'}:
        return 'heading', -.13, 1.8
    return 'word', 0.0, 0.0


def beginning(s, kind, base):
    if s == 'Title':
        return 9.5
    if s in {'The', 'A', 'An'}:
        return 2.5
    if s in {'I', 'You', 'We', 'It', 'He', 'She', 'This', 'That'}:
        return 1.25
    if s in {'import', 'package', 'from', '#include'}:
        return 2.8
    if kind == 'heading':
        return 6.0 if s == '#' else 3.4
    if kind == 'word':
        return (.4 if s[:1].isupper() else .1) if not s.startswith(' ') else 0.0
    return 1.7 if kind in {'stop', 'comma', 'space'} else base


def step(carry, prefix, upstream):
    s, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    age, previous = (0, '') if carry is None or carry[0] != doc else carry[1:]
    kind, base, boost = boundary(s)
    value = base + boost / (age + 4) ** .5
    word = previous.strip()
    lower = word.lower()
    if age == 0:
        value = beginning(s, kind, base)
    elif kind not in {'word', 'markup'}:
        if previous[-1:].isdigit():
            if kind == 'space':
                value += .45
            elif kind in {'indent', 'paren', 'heading'}:
                value -= .12
            else:
                value -= .65 if kind in {'stop', 'newline'} else .5
        elif previous[-1:].isspace():
            if kind in {'space', 'indent', 'paren', 'heading'}:
                value -= .1
            else:
                value -= .25 if kind == 'block' else .65
        elif not previous[-1:].isalpha():
            if kind == 'newline':
                value += .5
            elif kind in {'space', 'indent', 'paren', 'heading'}:
                value -= .2
            elif kind != 'block':
                correction = .9 if kind == 'comma' else .6 if kind == 'equals' else .35
                value -= correction
        if kind == 'comma' and lower in DISCOURSE:
            value -= .6 + .65 * word[:1].isupper()
        if kind == 'space':
            value += .9 * (lower in MONTHS) - .35 * (lower in FUNCTION_WORDS)
        if kind == 'newline' and lower in FUNCTION_WORDS:
            value -= .35
        initial = word.lstrip('.')
        if kind == 'stop' and (lower in ABBREVIATIONS or
                (len(initial) == 1 and initial.isascii() and
                 (initial.isupper() or word.startswith('.')))):
            value -= .5
    return (doc, age + 1, s), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:3597 - a punctuation / clause-boundary detector.

What it does, in plain terms: this component switches on at the punctuation that ends a
sentence or clause, and at line breaks. It is strongest on full stops, question and
exclamation marks, semicolons and newlines that follow them (and on the newline after a
chat tag such as "user"). It is medium on commas, colons, "=", the closing quote in '",' and
'":', and the word " and". It is weak on a bare space before a month's day number. It is
off for almost all other tokens, including words, digits and brackets.

Two modifiers:
- Right after a number (e.g. "1." or "2,") the punctuation response is weaker (x0.6).
- It is strongest at the start of a document and fades over the first few hundred
  tokens (factor 0.8 + exp(-age/50), age = tokens since the document began).

The program is a hand-set table of token classes, not a fitted model. Its weights were read
off the component's mean activation per class on training rows.
"""
import math

READS = ()

# Sentence-final punctuation, and line breaks that follow it or start a line.
SENTENCE_END = set(".!?。？！;；…")
# Commas, colons and equals signs, including full-width variants.
CJK_COMMA = set("，、")
COLON_EQ = set(":：=")
# Closing quote + separator, e.g. '",' or '":'.
CLOSE_QUOTE = {'",', "',", '":', '";', "');"}
# Month names with a leading space: the space before a day number after them is active.
MONTHS = {" January", " February", " March", " April", " May", " June", " July",
          " August", " September", " October", " November", " December", " Sep"}
# Chat-template tags: a newline right after one of these is strongly active.
CHAT_TAGS = {"user", "assistant", "<|im_end|>", "<tool_response>", "<tool_call>"}


def step(carry, prefix, upstream):
    # carry = (document id, tokens since that document began); resets on a new document.
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age = 0
    else:
        age = carry[1] + 1
    carry = (doc, age)

    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    core = s.replace("\n", "").strip()

    if "\n" in s and "\t" in s:
        base = 0.0  # indented code lines do not fire
    elif "\n" in s:
        if core == "" or all(c in SENTENCE_END for c in core):
            base = 1.5  # newline after a full stop, or a bare newline
        elif core[-1:] in ("{", ":"):
            base = 1.35  # newline after an opening brace or colon
        else:
            base = 0.75  # newline after a closing bracket, quote, etc.
        if prev.strip() in CHAT_TAGS:
            base = 2.5
    elif core and all(c in SENTENCE_END for c in core):
        base = 1.5  # . ! ? 。 ； etc.
    elif s == ",":
        base = 1.0
    elif s in CJK_COMMA:
        base = 1.2
    elif core in COLON_EQ or s in (" =", " :"):
        base = 0.95
    elif s in CLOSE_QUOTE:
        base = 0.9
    elif s == " and":
        base = 0.8
    elif s == " ":
        base = 1.3 if prev in MONTHS else 0.3
    elif s == ")":
        base = 0.15
    else:
        base = 0.0

    # Punctuation directly after a number is weaker.
    if base > 0 and s != " " and prev.strip().isdigit():
        base *= 0.6

    return carry, base * (0.8 + math.exp(-age / 50))

programs.luna:
"""Predicts a structural-marker signal: punctuation and line breaks stand out,
with a smaller response to 'and' and common code operators.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()

    if "\n" in token or "\r" in token:
        return None, 1.6
    if not text:
        return None, 0.05
    if text.casefold() == "and":
        return None, 0.75
    if any(mark in text for mark in ".!?。！？"):
        return None, 1.5
    if any(mark in text for mark in ",，"):
        return None, 1.0
    if any(mark in text for mark in ":;{}="):
        return None, 1.0
    if any(mark in text for mark in "<>+-*/"):
        return None, 0.35
    return None, 0.05

"""A conservative Italian cue: particles are positive; common participle endings negative."""

READS = ()

ITALIAN_WORDS = {
    "ai", "al", "alla", "che", "ci", "come", "con", "da", "del", "della",
    "di", "e", "ed", "è", "gli", "il", "in", "la", "le", "non", "per",
    "si", "sono", "una", "un", "vi",
}
PARTICLES = {"ai", "che", "ci", "come", "e", "ed", "non", "si", "vi"}
PARTICIPLES = ("ato", "ata", "ate", "uto", "uta", "ito", "ita")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, history = carry if carry is not None else (doc, ())
    if doc != old_doc:
        history = ()

    token = prefix.token_strings[-1].strip().lower()
    piece = ""
    for char in token:
        if char.isalpha():
            piece += char
        else:
            piece = ""
    history = (history + (piece,))[-20:]
    italian = sum(word in ITALIAN_WORDS for word in history) >= 2

    value = 0.0
    if italian and piece.endswith(PARTICIPLES):
        value = -0.20
    elif italian and piece in PARTICLES:
        value = 0.20
    return (doc, history), value

