programs.sol:
"""Approximate the component's negative response to markup boundaries.

Opening HTML/XML tag endings get the largest negative values, especially
text formatting and table cells. Newlines, closing tags and type brackets
weaken them. Nearby closing tags identify established markup. Smaller rules
cover entity endings, LaTeX environment names/braces, comments, attribute
URLs and tool wrappers. A 400-character buffer resets per document.
Unrecognized text gets zero; weak lexical responses are deliberately omitted.
"""
import re

READS = ()

TEXT_TAGS = set('a b strong i em code tt sub sup span label button title legend '
             'th td summary'.split())
BLOCK = set('div p li ul ol dl dt dd pre blockquote body head html main section '
            'article table tr tbody thead tfoot form h1 h2 h3 h4 h5 h6 script '
            'style details header footer select option textarea'.split())
VOID = set('br hr img input link meta source wbr area base col embed param '
           'track'.split())
TYPES = set('int float double long short byte char boolean bool void string '
            'object number any unknown never null extends super'.split())
FORMATTING = set('em b strong code tt sub sup'.split())
MATH_ENVIRONMENTS = set('equ equatio equation align aligned alignat array matrix '
                        'pmatrix bmatrix Bmatrix vmatrix cases split gather '
                        'gathered multline eqnarray tabular smallmatrix'.split())

# Tuple order: bare delimiter, newline, punctuation, next tag, attached word.
WEAK_BOUNDARIES = {
    'closing': (-0.66, -0.18, -0.47, -0.12, -0.48),
    'type': (-0.47, -0.47, -0.33, -0.84, -1.58),
    'missing': (-0.09, -0.24, -0.31, -0.68, -0.74),
    'self_closing': (-0.29, -0.35, -0.48, -0.32, -0.40),
}
OPENING_SUFFIX = (-0.76, 0.42, 0.08, 0.36, -0.82)


def angle_value(token, recent):
    if '>' not in token or token.startswith('<|'):
        return None
    before, after = token.split('>', 1)
    allowed = set(" \t\"'/}\\;%()=")
    if any(c not in allowed for c in before):
        return None
    if '=' in before and not before.endswith('"'):
        return None
    if ')' in before and '"' not in before:
        return None
    if after.startswith('>'):
        return None
    if token.startswith(' ') and not before.strip():
        return 0.0  # Comparisons and Markdown quote markers.
    suffix = (0 if not after else 1 if after[0] in '\n\r' else
              3 if after.startswith('<') else 4 if after[0].isalnum() else 2)
    match = re.search(r'<([^<>]*)$', recent + before)
    tag = match[1] if match else ''
    name_match = re.match(r'/?([\w:.-]+)', tag)
    name = name_match[1] if name_match else ''
    attributes = '=' in tag
    if not name or (not attributes and re.search(r'[\n;()]', tag)):
        if before.endswith(('"', "'")):
            # A closing attribute quote is recognizable even in a truncated tag.
            return (-1.52, -1.20, -0.60, -1.00, -0.74)[suffix]
        if after.startswith('='):
            return None
        return WEAK_BOUNDARIES['missing'][suffix]
    if tag.startswith('/'):
        return WEAK_BOUNDARIES['closing'][suffix]
    if before.endswith('/'):
        return WEAK_BOUNDARIES['self_closing'][suffix]
    left = (recent + before)[:match.start()] if match else ''
    type_bracket = name.lower() in TYPES or (
        name[0].isupper() and (len(name) == 1 or
        bool(left) and (left[-1].isalnum() or left[-1] in '_:')))
    if not attributes and type_bracket:
        return None if after.startswith('=') else WEAK_BOUNDARIES['type'][suffix]

    name = name.lower()
    value = (-2.05 if name in TEXT_TAGS else -1.87 if name in BLOCK else
             -1.24 if name in VOID else -1.08)
    value += OPENING_SUFFIX[suffix]
    if name in FORMATTING:
        value -= 0.31
    if name in {'td', 'th'} and not attributes:
        value -= 1.27
    if name in {'title', 'legend'}:
        value -= 0.94
    # Attached content produces a stronger boundary response. Bare unfamiliar
    # fields are stronger in established XML than in isolated angle brackets.
    if before.endswith('"') and attributes:
        value += 0.17
    if after and after[0] in '{$&/@':
        value -= 0.75
    if after and after[0] in "'\"" and attributes:
        value -= 0.69
    if name not in TEXT_TAGS | BLOCK | VOID and not after:
        value += 0.57
        if '</' in left:
            value -= 1.31
    return value


def other_value(token, recent, previous):
    if '-->' in token:
        return -0.52
    if token == '<tool_call>':
        return -0.165
    if token == '<tool_response>':
        return 0.095
    if token in ('</tool_call>', '</tool_response>', '</think>'):
        return -0.07
    if token.startswith(';'):
        entity = re.search(r'&(#(?:[0-9]+|x[0-9A-Fa-f]+)|[A-Za-z]+)$', recent)
        if entity:
            return -0.90 if entity[1] in ('lt', 'gt') else -0.38
    environment = re.search(r'\\(begin|end)\{([^{}]*)$', recent)
    if environment:
        command, name = environment.groups()
        if token.startswith('}'):
            if command == 'end':
                return -0.07
            return -1.30 if name.rstrip('*') in MATH_ENVIRONMENTS else -0.80
        name += token
        if command == 'begin' and name in MATH_ENVIRONMENTS:
            if name == 'pmatrix':
                return -2.60
            if name == 'bmatrix':
                return -1.95
            return -0.76
    if token in ('http', 'https') and previous.endswith('="'):
        return -0.22
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        recent, previous = '', ''
    else:
        _, recent, previous = carry
    token = prefix.token_strings[-1]
    value = angle_value(token, recent)
    if value is None:
        value = other_value(token, recent, previous)
    return (document, (recent + token)[-400:], token), float(value)

programs.haiku:
"""Closing '>' of an opening markup tag (HTML/XML), e.g. the '>' in <td> or <a href="...">.

Layer-0 MLP unit 3600 of Qwen3-1.7B goes negative on the '>' that ends an opening tag
in markup text. How negative depends on the tag: table cells <td> and <th> are the
strongest (about -4); other short lowercase tags such as <tr>, <tt>, <a>, <hr> are
strong (about -2); table rows, blocks and other tags are moderate (about -1.5) and
longer or unusual tag names are weaker (about -0.8). Closing tags (</td>) and
chat-template tags (<think>, <tool_call>, <tool_response>) give nothing. Everywhere else
(ordinary text, code, comparisons) the unit is near zero.

The program reads the row left to right, keeping a small state: whether the text is
inside an opening tag ('<' then a letter, up to its '>') and the tag's name. The state
resets at each new document in a packed row.
"""

READS = ()

TABLE_CELL_TAGS = {"td", "th"}
ROW_AND_BLOCK_TAGS = {"tr", "thead", "tbody", "table", "div", "pre", "h4", "button", "summary"}
IGNORED_TAGS = {"think", "tool_call", "tool_response"}


def tag_value(name):
    if name in IGNORED_TAGS:
        return 0.0
    if name in TABLE_CELL_TAGS:
        return -4.0
    if len(name) <= 2 and name.islower():
        return -2.0
    if name in ROW_AND_BLOCK_TAGS:
        return -1.5
    return -0.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, None, "")  # (document, tag state, tag name)
    _, state, name = carry
    value = 0.0
    for ch in prefix.token_strings[-1]:
        if state is None:
            if ch == "<":
                state, name = "start", ""
        elif state == "start":
            if ch == "/":
                state = "closing"
            elif ch.isalpha():
                state, name = "name", ch
            else:
                state = None
        elif state == "name":
            if ch.isalnum() or ch in "_-:.":
                name += ch
            else:
                state = "attributes"
                if ch == ">":
                    value, state = tag_value(name), None
        elif state == "attributes" and ch == ">":
            value, state = tag_value(name), None
        elif ch == "<":
            state, name = "start", ""
    return (doc, state, name), value

programs.luna:
"""Flag likely markup, entity, shell-redirection, and TeX delimiters; otherwise stay quiet."""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = "" if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = 0.0

    if ">" in token:
        left = text.rfind("<")
        right = text.rfind(">")
        if left > right:
            name = text[left + 1:]
            closing_tag = name.startswith("/")
            if closing_tag:
                name = name[1:]
            before = text[left - 1:left]
            starts_tag = bool(name) and (
                name[0].isalpha() or name[0] in "!?"
            )
            left_boundary = not before or not (
                before[-1].isalnum() or before[-1] == "_"
            )
            if starts_tag and (left_boundary or closing_tag):
                value = -0.95

    if token.startswith(";") and "&#" in text[-12:]:
        digits = text.rsplit("&#", 1)[-1]
        if digits and digits.isdigit():
            value = -0.34

    if ">&" in token and text[-1:].isdigit():
        value = -0.6
    if token.startswith(">/") and text.endswith("&"):
        value = -0.6

    if "}{" in token and "\\begin{" in text[-100:]:
        value = -1.15
    if token.startswith("}") and "\\begin{" in text[-100:]:
        if text.rfind("\\begin{") > text.rfind("}"):
            value = -1.15

    combined = (text + token)[-256:]
    return (doc, combined), float(value)

programs.sol:
"""Recognize some split word stems, especially 'ge' and scientific combining
forms cut before their linking vowel (aut-o, hom-o, phot-o, prot-o, radi-o).
The same fragments have larger responses at document onset. Two familiar
collocations, co-homology and genetic algorithm, get an additional boost.
The English 'wh' fragment also receives a positive response. Other tokens
receive a small baseline; most weak lexical variation is left unmodeled.
"""
READS = ()
SCIENTIFIC_STEMS = frozenset(('aut', 'hom', 'phot', 'prot', 'radi'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1] + 1, carry[2]
    token = prefix.token_strings[-1]
    stem = token.strip(' ._/-')
    lower = stem.lower()
    spaced = token.startswith(' ')
    value = 0.002

    if lower == 'ge':
        if stem.isupper():
            base, onset = (0.23 if spaced else 0.11), 1.4
        elif stem.istitle():
            base, onset = (0.48 if spaced else 0.40), 1.85
        else:
            base, onset = (0.37 if spaced else 0.17), 1.20
        value = onset if position == 0 else base
        if 0 < position < 10:
            value += 0.5 / position
    elif lower in SCIENTIFIC_STEMS:
        value = 0.22 if spaced else 0.16
        if lower == 'prot':
            value = 0.26
        if lower == 'hom' and previous.lower().strip() == 'co':
            value = 0.55
        if position == 0:
            value = 1.0 if lower != 'hom' else 0.8
        elif position < 10:
            value += 0.5 / position
    elif lower == 'wh':
        value = 0.23 if stem == 'Wh' and spaced else 0.09
        if position == 0:
            value = 1.1
    elif lower == 'algorithm' and previous.strip().lower() == 'genetic':
        value = 0.55

    return (doc, position, token), float(value)

"""A token-local detector for 'def' and mixed tab/space indentation.

The prediction ignores surrounding language. Bare 'def' is stronger than its
spaced form. Indentation strength depends on its width: three spaces after one
tab are unusually weak; wider four-column offsets are strong. Other tokens
get zero.
The many smaller, token-specific background responses are not modeled.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.lstrip(' \t._-:')
    if word.lower() == 'def':
        if word == 'DEF' or token.startswith('_'):
            value = 0.48
        elif token == 'def':
            value = 0.88
        else:
            value = 0.71
    elif '\t' in token and ' ' in token and not token.strip():
        spaces = token.count(' ')
        if '\n' in token or '\r' in token:
            value = 0.25
        elif token.startswith(' ') or token.endswith('\t'):
            value = 0.45 if spaces > 1 else 0.10
        elif token.count('\t') > 1:
            value = 0.75
        elif spaces == 3:
            value = 0.37
        elif spaces <= 4:
            value = 0.59 if spaces == 1 else 0.53
        elif spaces % 4 == 1:
            value = 0.87
        else:
            value = 0.71
    else:
        value = 0.0
    return None, value

programs.haiku:
"""Layer-0 MLP down-projection component 3604: a "type of" detector.

It fires on the word " of" when the word just before it is a noun that names a
kind, sort or category ("types of", "kind of", "sort of", "variety of", "species
of", "method of", "size of"...). The strongest response is to "type(s)" and
"kind(s)"/"sort(s)"; weaker for quality/feature nouns ("form of", "quality of",
"purpose of"). Slightly negative after "because of", "view of", "end of",
"front of", "result of" and similar. Everywhere else it is near zero.

Rows are packed documents: a word only counts if it sits in the same document
as the " of" (the model resets context at a document change).
"""

KIND_NOUNS = {"type", "types", "kind", "kinds", "sort", "sorts"}
CATEGORY_NOUNS = {
    "species", "method", "methods", "style", "variety", "varieties", "choice",
    "size", "sizes", "class", "classes", "category", "categories",
}
FEATURE_NOUNS = {
    "form", "forms", "quality", "purpose", "purposes", "importance",
    "characteristic", "characteristics", "feature", "features", "development",
    "length", "version", "versions", "parts", "part", "piece", "role", "process",
    "age", "shape", "mode", "change", "changes",
}
POSITION_OR_CAUSE_NOUNS = {
    "because", "view", "end", "front", "side", "top", "result", "results", "all",
    "each", "terms", "expression", "effect", "effects", "notice", "presence",
    "basis", "bottom", "middle", "right",
}

READS = ()


def step(carry, prefix, upstream):
    """Activation at this position: large if the token is " of" right after a kind noun."""
    if len(prefix.token_strings) < 2 or prefix.token_strings[-1] != " of":
        return None, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    word = prefix.token_strings[-2].strip().lower()
    if word in KIND_NOUNS:
        value = 1.4
    elif word in CATEGORY_NOUNS:
        value = 0.9
    elif word in FEATURE_NOUNS:
        value = 0.35
    elif word in POSITION_OR_CAUSE_NOUNS:
        value = -0.3
    else:
        value = 0.0
    return None, value

programs.sol:
"""Lexical alternatives, quantified units, and reference/aside cues.

Large responses match 'or' and several translations, or units after a
numeral. Number words and vague quantities produce weaker unit responses.
Plural durations also have an ordinary-use response. 'Of' after plural
magnitudes/durations, reference 'see', parenthetical 'born', reconsideration
words, and quoted container openings are additional cues. 'Can/could see'
and a spaced percent sign receive small negative responses.

Only two preceding tokens are remembered, resetting at document boundaries.
This recognizes split unit words and whitespace between number and unit.
Everything unmatched is zero; weak word-specific effects are omitted.
"""
READS = ()
NUMBER_WORDS = set('''one two three four five six seven eight nine ten eleven
 twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen twenty
 thirty forty fifty sixty seventy eighty ninety hundred thousand million
 billion trillion'''.split())
QUANTIFIERS = set('''a an few several many couple more less multiple half
 quarter dozen some of per'''.split())
DURATIONS = {  # ordinary use, immediately following digits
    'years': (.25, .90), 'months': (.33, .98), 'weeks': (.32, 1.23),
    'days': (.16, 1.02), 'hours': (.22, 1.07), 'minutes': (.48, 1.26),
    'seconds': (.64, 1.43), 'decades': (.22, .70), 'centuries': (.37, .75),
}
PHYSICAL = set('''inch foot mile yard meter metre kilometer kilometre
 millimeter millimetre centimeter centimetre gram kilogram ounce pound
 ton tonne liter litre gallon acre hectare watt volt ohm'''.split())
METRIC = set('''mm cm km mg kg ml mL nm mph Hz kHz MHz GHz kW kWh
 kPa MPa rpm ppm mM mA'''.split())
# Recognizable unit families: ordinary and numeral-conditioned responses.
UNIT_FAMILIES = (
    (set('year month week day hour minute second'.split()), -.02, .60),
    (set('million billion trillion crore'.split()), .45, 1.40),
    (set('millions billions thousands'.split()), .58, .75),
    (set('min sec ms ns ft lb oz dB'.split()), .08, .65),
    (set('KB kB MB GB TB kb mb gb tb bytes'.split()), .05, .63),
    (set('AM PM am pm UTC GMT'.split()), .05, .60),
    (set('teaspoon teaspoons tablespoon tablespoons tsp tbsp'.split()), .45, .65),
    (set('dollar dollars euro euros cent cents'.split()), .12, .65),
    (set('horas anos años ans anni dias días jours дней лет года году год'.split()),
     .10, .70),
    (set('см мм км кг'.split()), .25, .95),
    (set('px pages'.split()), .10, .80),
    (set('words views'.split()), .05, .45),
    (set('年 日 天 元 克 米 岁 歲 倍 일 秒 円 号 字'.split()), .10, .88),
    (set('分钟 分鐘 小时 小時 公斤 公里 公顷 平方米 毫米 千米'.split()), .45, 1.25),
)


def unit_range(word, spaced):
    """Ordinary/quantified strengths, grouped by familiar unit families."""
    lower = word.lower()
    if lower in DURATIONS:
        low, high = DURATIONS[lower]
        scale = 1. if word == lower else .75
        return low * scale, high * scale
    singular = {'feet': 'foot', 'inches': 'inch', 'lbs': 'pound'}.get(lower, lower[:-1])
    if singular in PHYSICAL and (lower.endswith('s') or lower == 'feet'):
        return (.50 if spaced else .05, 1.22)
    if lower in PHYSICAL:
        return (.20 if spaced else 0., .72)
    if word in METRIC:
        return (.32 if spaced else .12, .95 if word in {'mM', 'mL'} else 1.16)
    if word in {'m', 'g', 'l'}:
        return (.01, .38)
    if word in {'thousand', '千'}:
        return (.35, .85)
    if word == 'hundred':
        return (.16, .55)
    if word in {'degrees', '°'}:
        return (.12, .88)
    if word in {'°C', '°F', '℃'}:
        return (.65, 1.07)
    if word in {'percent', '％'}:
        return (.15, 1.02)
    if word in {'万', '萬', '亿', '億'}:
        return (.45, 1.45 if word in {'万', '萬'} else 1.85)
    if (word and word[0] in '万萬亿億' and len(word) <= 3
            and word[-1] in '元人吨噸台辆輛个個家户戶'):
        return (.70, 1.90 if word.endswith('元') else 1.40)
    if word.startswith('/') and word[1:] in METRIC:
        return (.45, .60)
    for words, low, high in UNIT_FAMILIES:
        if word in words:
            return low, high
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, before = carry[1:] if carry and carry[0] == doc else ('', '')
    token = prefix.token_strings[-1]
    word, spaced = token.strip(), token.startswith(' ')
    prior_word = prev.strip().lower()
    numeral = bool(prev) and prev[-1].isdigit()
    boundary = spaced or not prev or not prev[-1].isalnum()
    value = 0.
    if word.lower() == 'or':
        if word == 'OR':
            value = .76 if boundary else .23
        elif word == 'Or':
            value = .88 if spaced else 1.0
        else:
            value = (.90 if numeral else .96) if boundary else .16
    elif word in {'/or', '_or', '-or', '.or'}:
        value = .82
    elif word in {'或', '或者', 'أو', '또는', 'atau', 'hoặc', 'または'}:
        value = .72
    elif word in {'oder', 'или'}:
        value = .56 if boundary else .10
    elif word in {'veya', 'ou'}:
        value = .35 if spaced else 0.
    elif word == 'nor':
        value = .33
    elif word == 'born':
        value = .70 if prev.rstrip().endswith('(') else .16
        if prev.rstrip().endswith((',', ';')):
            value = .41
    elif word.lower() == 'see':
        value = .90 if not spaced or word == 'See' else .20
        if prev.rstrip().endswith(';'):
            value = 1.25
        elif prev.rstrip().endswith(','):
            value = 1.12
        elif prev.rstrip().endswith('('):
            value = 1.05
        if prior_word in {'please', 'and', '&'}:
            value = .53
        elif prior_word in {'can', 'could'}:
            value = -.18
    elif word.lower() in {'where', 'wherein'}:
        value = .15
    elif word in {'Wait', 'wait'}:
        value = .30 if word == 'wait' else .36 if spaced else .414
    elif word in {'Alternatively', 'alternatively'}:
        value = .54 if word[0].isupper() else .13
    elif word in {'{"', "{'", '["', "['"}:
        value = .45 if word[0] == '{' else .22
    elif word == 'cent' and prior_word == 'per':
        value = .60
    elif word == 'of':
        if prior_word in {'thousands', 'millions', 'billions'}:
            value = .61
        elif prior_word in {'hundreds', 'dozens'}:
            value = .30
        elif prior_word in DURATIONS or prior_word in METRIC:
            value = .30
    else:
        hyphenated = word.startswith('-')
        unit = unit_range(word[1:] if hyphenated else word, spaced)
        # A unit word may be split: 'cent' + 'imeter', 'mill' + 'imeters'.
        complete = prior_word + word
        if not spaced and word and complete in METRIC:
            unit = (.20, .85)
            numeral = bool(before) and before[-1].isdigit()
        elif not spaced and word and complete in PHYSICAL:
            unit = (.40, .85)
            numeral = bool(before) and before[-1].isdigit()
        elif not spaced and complete.endswith('s') and complete[:-1] in PHYSICAL:
            unit = (.50, 1.10)
            numeral = bool(before) and before[-1].isdigit()
        if word == '%' and spaced:
            unit = (-.13, .10)
        elif token.startswith('%'):
            high = .92 if token == '%' else .65 if ',' in word else .42
            unit = (-.06, high)
        if unit is not None:
            low, high = unit
            fraction = (1. if numeral else .75 if prior_word in NUMBER_WORDS
                        else .40 if prior_word in QUANTIFIERS else 0.)
            if prev.isspace() and before and before[-1].isdigit():
                fraction = .60
            elif prev and prev[-1].isnumeric() and not numeral:
                fraction = .80
            value = low + fraction * (high - low)
            if hyphenated:
                value = .75 * value + .15 if fraction >= .75 else 0.
    return (doc, token, prev), float(value)

programs.haiku:
"""Quantity-unit and alternative-word detector (layer-0 MLP feature).

Component layers.0.mlp.down_proj:3605 writes a positive signal on:
1. The word "or" between alternatives (" or", "Or", " OR", "/or"): the largest, steady.
2. Measurement units and scale words right after a number ("20 km", "3.5 million",
   "30 seconds", "5 mg", "2 亿"), and "%" after a number. Strongest right after a digit.
3. Weaker: "see"/"See" (citations), and the reasoning openers "Wait" and "Alternatively".
Everything else is 0.
"""

READS = ()

OR_WORDS = {" or", "Or", " Or", " OR", "/or"}
SEE_WORDS = {" see", "see", " See", "See"}
SCALE = {"million", "billion", "thousand", "万", "亿", "万元", "亿元", "万吨"}
OPENERS = {"Wait", " Wait", "Alternatively", " Alternatively"}
UNITS = set("""
 km mm cm nm meters metres kilometres miles feet inches yards
 kg mg grams pounds ounces lb ml seconds minutes hours days weeks months years
 million billion thousand percent %
 °C °F ° Hz MHz GHz kB px ms
 万 亿 元 万元 亿元 千米 毫米 分钟 小时 日 年 月 万吨
""".split())

def _is_number(s):
    return any(c.isdigit() for c in s)

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = ""
    if prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    if cur in OR_WORDS:
        return carry, 1.0
    if cur in SEE_WORDS:
        return carry, 0.5
    if cur in OPENERS:
        return carry, 0.45
    if cur.strip() in UNITS:
        return carry, (1.6 if cur.strip() in SCALE else 1.1) if _is_number(prev) else 0.4
    return carry, 0.0

programs.luna:
"""Pulse on alternative/correction words and a number followed by a unit."""

READS = ()

ALTERNATIVES = {"or", "alternatively", "wait", "unless", "either", "otherwise"}
UNITS = {
    "year", "years", "month", "months", "week", "weeks", "day", "days",
    "hour", "hours", "minute", "minutes", "second", "seconds",
    "kg", "km", "miles", "mile", "inches", "inch", "degrees",
    "ounce", "ounces", "hectare", "hectares", "mb", "gb", "million", "%",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().casefold()
    if token in ALTERNATIVES:
        return None, 1.0

    same_document = (
        len(prefix.document_ids) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    if token in UNITS and same_document:
        previous = prefix.token_strings[-2].strip()
        if any(char.isdigit() for char in previous):
            return None, 1.0
    return None, 0.0

