READS: tuple[str, ...] = ()

BE = {'am', 'is', 'are', 'was', 'were'}
DO = {'do', 'does', 'did'}
HAVE = {'have', 'has', 'had'}
MODALS = {'can', 'could', 'may', 'might', 'will', 'would', 'shall', 'should', 'must'}
SUBJECTS = {'i', 'you', 'he', 'she', 'it', 'we', 'they', 'there', 'this', 'that'}
