    'could': -0.068, 'may': -0.021, 'might': -0.030,
    'would': 0.034, 'should': 0.029, 'shall': 0.102, 'must': 0.024,
    'some': 0.024, 'any': -0.030, 'every': 0.065, 'each': -0.021,
    'enough': 0.099, 'various': 0.085, 'single': -0.061,
    'hundred': 0.145, 'thousand': 0.175, 'million': 0.051,
