    if word == 'two':
        value = {'no': 1.16, 'any': 0.81, 'only': 0.63, 'every': 0.51,
                 'a': 0.34, 'each': 0.34, 'other': 0.34, 'least': 0.34,
                 'most': 0.37, 'exactly': 0.27, 'than': 0.23,
                 'just': 0.29, 'all': 0.30, 'the': -0.01}.get(prev, 0.082)
