    elif word == 'new':
        value = {'a': 0.20, 'all': 0.23, 'the': -0.05}.get(prev, 0.023)
        if prev in {'no', 'any', 'every', 'each', 'one'}:
            value = 0.32
    elif word == 'other':
        value = {'no': 0.38, 'any': 0.19, 'each': 0.16, 'every': 0.10,
                 'only': 0.20, 'one': 0.19, 'all': 0.09,
                 'the': -0.05}.get(prev, 0.0)
    elif word == 'another' and prev == 'one':
        value = 0.26
    elif word == 'single' and prev == 'every':
        value = -0.30
    elif word == 'few':
        value = 0.15 if prev in {'a', 'every'} else 0.038
        if prev in {'first', 'last'}:
            value = 0.0
    elif prev == 'no' and word in {'harm', 'need', 'more', 'further'}:
        value = 0.52 if word == 'harm' else 0.30

    # Partitive quantities and auxiliary constructions.
    if word == 'of':
        if prev in {'all', 'both', 'kind', 'sort', 'couple', 'plenty'}:
            value = -0.11
        elif prev == 'one':
            value = -0.05
        elif prev == 'out':
            value = 0.05
    elif word == 'have':
        value = {'to': -0.086, 'must': 0.13, 'would': 0.066}.get(prev, value)
    elif word == 'be' and prev == 'to':
        value = -0.033

    # Question heads override the ordinary lexical/quantity response.
    if prev == 'why':
        if word in {'does', 'should'}:
            value = 1.30
        elif word in BE | DO:
            value = 1.10 if word in {'is', 'are'} else 1.00
            if word in {'was', 'were', 'am'}:
                value = 0.85
        elif word in HAVE | {'will', 'would', 'must', 'shall'}:
            value = 0.80
        elif word in MODALS:
            value = 0.50
        elif word in NEGATED:
            value = 0.44
        elif word == 'some':
            value = 0.79
        elif word in DETERMINERS | {'it', 'there', 'all', 'so'}:
            value = 0.32
        elif word in SUBJECTS:
            value = 0.20 if word in {'you', 'they'} else 0.13
    elif prev in {'how', 'where', 'when'}:
        if word in BE | DO:
            value = 0.30 if prev == 'how' else 0.24
            if word == 'does':
                value += 0.07
        elif word in MODALS:
            value = 0.11 if word == 'could' else 0.21
    elif prev == 'what':
        if word in BE | DO:
            value = 0.22 if word == 'does' else 0.12
        elif word in MODALS:
            value = 0.21 if word in {'will', 'would', 'should'} else 0.09
        elif word in DETERMINERS | SUBJECTS:
            value = -0.13 if word in {'it', 'this', 'a'} else -0.08
    elif before == 'why':
        if prev in SUBJECTS and word in AUXILIARIES:
            value = 0.25 if word != 'should' else 0.38
        elif prev in NEGATED | {'can'} and word in {"'t", '’t'}:
            value = 0.38
    return float(value)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    _, prev, before = (doc, '', '') if reset else carry
    word = prefix.token_strings[-1].strip().lower()
    value = response(word, prev, before)
    return (doc, word, prev), float(value)

programs.haiku:
"""Fires on the word after "why" when it is an auxiliary verb (why does / why is /
why should), and on counting words after "no", "only", "any" or "every" (no one,
no two, only two); it is weakly positive on a few quantity and comparison words
(two, few, every, than, new, other) and on auxiliaries after "how" or "what".

The component reads the current token together with the one before it, and nothing
across a document boundary. Every other position predicts 0.
"""

READS = ()

AUXILIARIES = {"does", "do", "did", "is", "are", "was", "were", "should", "would",
               "can", "could", "will", "have", "has", "am"}
COUNTING = {"one": 0.7, "two": 1.1, "other": 0.4}
QUANTITY = {"two": 0.1, "few": 0.12, "every": 0.07, "than": 0.065, "new": 0.04,
            "other": 0.02}


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    prev = _word(prefix.token_strings[-2])
    cur = _word(prefix.token_strings[-1])
    if prev == "why":
        return None, 1.0 if cur in AUXILIARIES else 0.15
    if prev in ("no", "only", "any", "every") and cur in COUNTING:
        return None, COUNTING[cur]
    if prev in ("how", "what") and cur in AUXILIARIES:
        return None, 0.2
    return None, QUANTITY.get(cur, 0.0)

programs.luna:
"""A sparse text cue for why-questions and quantifier phrases.

Most positions are left at zero.  The main positive cue is a word right after
“why”; a smaller cue marks familiar one/two/other quantifier phrases.
"""
READS = ()


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t - 1] != prefix.document_ids[t]:
        before = ""
    else:
        before = prefix.token_strings[t - 1].strip().lower()
    word = prefix.token_strings[t].strip().lower()

    if before == "why":
        return None, 0.75
    if before == "no" and word in {"one", "two", "other", "harm"}:
        return None, 0.7
    if before == "only" and word in {"one", "two", "some", "has"}:
        return None, 0.7
    if before in {"any", "every"} and word == "two":
        return None, 0.7
    return None, 0.0

programs.sol:
"""Approximate the component's negative lexical rest/remainder response.

'Rest' fires across senses: relaxation, leftovers, REST APIs, and word
fragments. 'The rest' is stronger, and 'rest of' continues onto 'of'.
Document-initial 'rest' has a stronger response. Smaller cues include
rest-related spellings and translations. Most unrelated
small lexical responses are deliberately omitted rather than memorized.
"""
READS = ()

# Related vocabulary, grouped by strength measured on training text.
CUE_GROUPS = (
    (-4.5, {'resting', 'rested', 'rests', 'resto'}),
    (-1.0, {'restore', 'restored', 'restoring', 'restores', 'restoration',
            'arrest', 'arrested', 'arrests', 'crest', 'unrest', 'restraint'}),
    (-1.7, {'restitution'}),
    (-1.2, {'restless', 'restroom'}),
    (-1.25, {'remainder', 'remainders'}),
    (-0.55, {'remaining'}),
    (-0.33, {'remain', 'remains'}),
    (-0.8, {'alternate'}),
    (-0.45, {'altern'}),
    (-0.3, {'alternative', 'alternatives', 'alternating'}),
    (-0.7, {'recess', 'refresh', 'serene', 'breath', 'breathe', 'breathing'}),
    (-0.35, {'relax', 'relaxed', 'relaxation', 'recreation', 'entertainment'}),
    (-0.23, {'sleep', 'pause'}),
    (-0.6, {'restart'}),
    (-0.75, {'.sleep'}),
)
CUES = {word: value for value, words in CUE_GROUPS for word in words}
TRANSLATED_CUES = {
    '休': -5.3, '休息': -6.2, '休み': -2.1, '歇': -2.6,
    '其余': -3.6, '余': -0.7, '剩余': -1.1, '剩下': -0.85,
    '息': -0.5, '呼吸': -0.5, '娱乐': -1.05, '恢复': -0.8,
    'отдых': -2.1, 'ост': -1.4, 'рест': -1.45, 'レスト': -2.0,
    'nghỉ': -1.6, 'autres': -0.8, 'altre': -1.0, 'altri': -0.6,
}
REST_ENDINGS = {
    'ing': -3.4, 'ed': -1.8, 'y': -1.5, 'os': -2.1,
    'room': -1.3, 'rooms': -1.3, 'ful': -1.0,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    new_document = carry is None or carry[0] != doc
    previous = '' if new_document else carry[1]
    old = previous.strip().lower()
    value = CUES.get(lower, TRANSLATED_CUES.get(lower, 0.0))

    if word == 'rest':
        if token[:1].isspace():
            value = -9.0 if old == 'the' else -7.3
            if old == 'a':
                value = -8.1
            elif old in {"'s", '’s', 'head', 'tool'}:
                value = -8.9
        elif previous[-1:].isalpha():
            value = -5.9 if old in {'back', 'arm'} else -3.8
        else:
            value = -6.5
    elif word == 'Rest':
        value = -6.6
    elif word == 'REST':
        value = -6.6 if token[:1].isspace() else -5.8
        if not token[:1].isspace() and previous[-1:].isupper():
            value = -3.7
    elif lower.lstrip('._/-(') == 'rest':
        value = -6.7
    elif lower.lstrip('._/') in {'restore', 'restored', 'restoring'}:
        value = -1.0
    elif lower == 'reste':
        value = -3.0 if token[:1].isspace() else -1.9
    elif lower == 'resta':
        value = -1.8
    elif lower == 'leisure':
        value = -0.85 if word.islower() else -1.5
    elif lower == 'other':
        if word != 'other':
            value = 0.35
        elif old == 'each':
            value = -0.70
        elif old in {'the', 'all', 'every'}:
            value = -0.30
        else:
            value = 0.08
    elif lower == 'others':
        value = -0.9 if old in {'the', 'all'} else -0.52
        if word != 'others':
            value = -0.35

    if word == 'of':
        if previous == ' rest':
            value = -5.8
        elif previous.strip() in {'Rest', 'REST'}:
            value = -4.9
        elif previous == 'rest':
            value = -2.6
        elif old == 'remainder':
            value = -1.1
    elif old.lstrip('._/-(') == 'rest':
        value = REST_ENDINGS.get(token, value)
    if new_document and lower == 'rest':
        # No preceding context: measured separately at document starts.
        if word == 'rest':
            value = -10.0 if token[:1].isspace() else -7.75
        elif word == 'Rest':
            value = -8.9
        else:
            value = -7.5 if token[:1].isspace() else -6.4
    return (doc, token), float(value)

"""Recognize a few opening/code markers and adjacent rounded-vowel spellings.

Package and namespace keywords give a negative response, stronger at a
fresh document opening or after a file header. Opening code markers also
receive a small negative response. Otherwise, an o/u-like vowel ending the
previous token favors l/r and s/t continuations, and opposes p/b or nasal ones.
Latin, Cyrillic and Greek letters are grouped by their usual sound classes.
Long continuations have a weaker response. This is a spelling heuristic, not
a pronunciation parser; spaces break the letter-continuation rule.
"""
import unicodedata

READS = ()


def unaccent(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if unicodedata.category(c) != 'Mn')


def continuation(previous, token):
    before = unaccent(previous)
    after = unaccent(token)
    if not before or not after:
        return 0.0
    if before[-1] in 'oоοω':
        strength = 1.0
    elif before[-1] in 'uуυ':
        strength = 0.77
    else:
        return 0.0
    if len(before.strip(' -._/"\'')) > 1:
        strength *= 0.88
    if len(after) >= 4:
        strength *= 0.47
    first = after[0]
    if first in 'lłľлλ':             # lateral consonants
        response = 2.43
    elif first in 'rřрρ':            # rhotic consonants
        response = 1.48
    elif first in 'pпπ':             # voiceless labial stops
        response = -0.93
    elif first in 'bбβ':             # b-like labials
        response = -0.61
    elif first in 'mnмнμν':          # nasal consonants
        response = -0.65
    elif first in 'stсσςтτ':          # s/t-like coronal consonants
        response = 0.54
    else:
        response = 0.0
    return strength * response


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, previous, opening, tail = 0, '', '', ''
    else:
        _, position, previous, opening, tail = carry
        position += 1
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip('-')
    # A short opening and recent line suffice; never reread the whole prefix.
    line_start = not tail.replace("\\n", "\n").rsplit("\n", 1)[-1].strip()
    file_header = opening.lstrip().startswith(('/*', '//'))
    php_header = opening.lstrip().lower().startswith('<?php')
    value = continuation(previous, token)
    if word == 'package':
        if position == 0:
            value = -21.51 if token == 'package' else -0.81
            if token == ' package':
                value = -5.47
        elif token == 'package':
            value = (-9.3 if file_header else -5.0) if line_start else -2.4
        else:
            value = -0.81
    elif word == 'packages':
        value = -0.1 if token == 'packages' else -0.45
    elif word == 'namespace':
        if position == 0:
            value = -3.51 if token == 'namespace' else -2.0
        elif php_header:
            value = -10.2
        elif token == 'namespace':
            value = -2.9 if line_start else -1.7
        elif token.startswith('\t'):
            value = -5.6
        else:
            value = -1.65 if token.strip() == 'namespace' else -0.95
    elif position == 0:
        if token and set(token) == {'#'}:
            value = -1.1 if len(token) <= 2 else -0.5
        elif token.startswith(('#!', '#if')):
            value = -1.0
        elif token.startswith(('/*', '//', '<?')):
            value = -0.85
        elif token in ('import', 'using', 'from'):
            value = -0.7
    opening = (opening + token)[:32]
    tail = (tail + token)[-128:]
    return (document, position, token, opening, tail), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 3608: a "source file opener" detector.

It responds negatively where a code file opens with a declaration keyword, the word
`package` (Java, Go, Kotlin) or `namespace` (C#, C++, PHP). It is strongest when that
keyword is the very first token of a document, where the model has no earlier context, so
the response depends only on the token itself. Mid-file uses of the keyword give smaller
negative responses. Everything else is near zero.

The program:
  * first token of a document = `package`                      -> -21.5 (the big spike)
  * first token of a document = other namespace/module openers -> about -1 to -5
  * `package`/`namespace` at the start of a line (after a licence comment or a blank line) -> -6
  * `package`/`namespace` elsewhere in code                     -> -2.5
  * ` package`/` namespace` with a leading space in prose or code -> -1.5
"""

READS = ()

STRONG_OPENERS = {" package", "namespace", "\tnamespace", "﻿namespace", " namespace"}
WEAK_OPENERS = {"#", "##", "#!/", "import", "using", "from", "//", "/*", "<?", "module", "#ifndef"}
KEYWORDS = {"package", "namespace"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    first = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if first:
        if tok == "package":
            return carry, -21.5
        if tok in STRONG_OPENERS:
            return carry, -4.0
        if tok in WEAK_OPENERS:
            return carry, -1.2
        return carry, 0.0
    if tok in KEYWORDS:
        prev = prefix.token_strings[-2]
        if "\n" in prev or prev.strip() == "":
            return carry, -6.0
        return carry, -2.5
    if tok in {" package", " namespace"}:
        return carry, -1.5
    return carry, 0.0

programs.sol:
"""A detector for the onset of capital lettering.

It responds chiefly to single capitals (initials, variables, split names,
and CamelCase). I is nearly ignored. Two-letter capital chunks respond
less, longer ones very little, except the name placeholder NAME.
Recent capital lettering, digits, and fused punctuation reduce the response.
Document starts are weak; other tokens receive a tiny constant baseline.
The larger alphabet calibration table changes strengths but not the detector;
this version retains only the strongest letter-specific differences.
"""
READS = ()

# Most letters have similar strength; these are the main exceptions.
LETTER_GAIN = {
    'A': 0.73,
    'E': 1.23,
    'I': 0.01,
    'O': 0.85,
    'Q': 0.78,
    'X': 0.70,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent = '', 0.0
    else:
        _, previous, recent = carry

    text = token.lstrip()
    letters = text.lstrip('.,-(/_\'"[]<>:=*')
    attached = letters != text
    uppercase = previous.strip().isupper()
    inside_word = (not token[:1].isspace() and not attached
                   and previous[-1:].isalpha())
    strength = 0.90 - 0.70 * recent
    if not previous:
        strength -= 0.85
    if uppercase:
        strength -= 0.43
    if previous[-1:].isdigit():
        strength -= 0.32
    if inside_word or attached:
        strength -= 0.20
    strength = max(-0.08, strength)

    value = 0.002
    if letters.isascii() and letters.isalpha() and letters.isupper():
        if len(letters) == 1:
            value = LETTER_GAIN.get(letters, 1.04) * strength
        elif letters == 'NAME':
            value = 0.81 * strength
        else:
            if len(letters) == 2:
                gain = 0.48
            elif len(letters) == 3:
                gain = 0.12
            else:
                gain = 0.07
            value = gain * strength - 0.06 * (uppercase or inside_word)

    # An exponentially fading measure of recent all-capital tokens.
    recent = 0.8 * recent + 0.2 * token.strip().isupper()
    return (doc, token, recent), float(value)

"""Approximate an ASCII digit-continuation signal.

Ordinary text and first digits are nearly silent. Later digits grow with
run length, with higher gains for 0, 1, 8 and 9. A preceding 1 or 2
weakens the response; a preceding zero favors small following digits.
Punctuation-separated number parts and hexadecimal-looking identifiers
get extra gain. Document-initial numbers have a separate, fading onset.
The constants are fitted gains for numeric values and familiar boundaries,
not vocabulary ids. Small word-specific and Unicode-digit signals are omitted.
"""
READS = ()

START_DIGIT = (1.22, .45, .06, .43, .75, .58, .93, 1.02, .91, 1.33)
DIGIT_GAIN = {0: 1., 1: .57, 8: .58, 9: .78}  # Digits 2--7: .44
RUN_BOOST = (0., .50, .96, 1.32, 1.68)
AFTER_ZERO_SMALL = (1.48, .65, .21, -.02)


def hex_letters(text):
    return bool(text) and all(c in 'abcdefABCDEF' for c in text)


def boundary_gain(text):
    if text in ('.', ',', ':', '-'):
        return .32
    if text == '/':
        return .18
    if hex_letters(text):
        return .40
    return 0. if text and set(text) == {'_'} else -.07


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    at_start = carry is None or carry[0] != doc
    previous, length, initial_run, boundary = (
        (-1, 0, True, 0.) if at_start else carry[1:]
    )
    text = prefix.token_strings[-1]
    if not (len(text) == 1 and '0' <= text <= '9'):
        return (doc, -1, 0, False, boundary_gain(text)), .001

    digit = int(text)
    length += 1
    value = .005
    if at_start:
        value = START_DIGIT[digit]
    elif previous == 0:
        value = (AFTER_ZERO_SMALL[digit] if digit < 4 else
                 -.03 if digit == 9 else -.21)
        value += .17 * min(length - 2, 5)
    elif previous > 0:
        prior_gain = (.12 if previous <= 2 else
                      .57 if previous == 3 else
                      1.08 if previous <= 5 else 1.43)
        value = DIGIT_GAIN.get(digit, .44) * (
            prior_gain + RUN_BOOST[min(length - 2, 4)]
        )
    elif hex_letters(prefix.token_strings[-2]):
        value = (.64 if digit == 0 else .58 if digit == 9 else
                 .45 if digit >= 6 else .30)

    if previous >= 0:
        value = .97 * value + boundary
    elif not at_start and prefix.token_strings[-2] in ('.', ','):
        value = -.06
    if initial_run and 2 <= length <= 4:
        value += 1.0 - .18 * length
    return (doc, digit, length, initial_run, boundary), float(value)

"""Respond to delimiter boundaries within a single punctuation token.

The largest responses are to close-and-reopen shapes such as ][ (array
indices), }{ and )( (mathematical groups), or >< (HTML-tag boundaries).
These are shape tests, not parsers for those languages. Bracket type,
intervening operators, earlier brackets, and newlines adjust the strength.
Lone opening parentheses and quote separators get smaller responses.
Tokens containing letters or digits, and unrecognized shapes, get zero.
The program uses no history, so context-dependent variations are omitted.
"""
import re

READS = ()
CLOSE = ')]}>'
OPEN = '([{<'
# Columns: opening round, square, curly, angle bracket.
STRENGTH = (
    (4.7, 2.1, 1.9, 0.0),  # Closing round
    (2.3, 7.0, 3.0, 0.0),  # Closing square
    (2.0, 1.8, 4.9, 0.0),  # Closing curly
    (1.3, 0.0, 0.9, 3.7),  # Closing angle
)
BOUNDARY = re.compile(r'([)\]}>])([^()\[\]{}<>]*)([(\[{<])')


def response(token):
    s = token.strip()
    if not s or any(c.isalnum() for c in s):
        return 0.0
    match = BOUNDARY.search(s)
    if match:
        close, bridge, opened = match.groups()
        i, j = CLOSE.index(close), OPEN.index(opened)
        value = STRENGTH[i][j]
        if i == j:
            if close == ')' and bridge:
                value *= 0.48 if '=' in bridge else 0.76
            elif close == ']' and bridge:
                value *= 0.82
            elif close == '}' and bridge:
                value *= 0.87 if '_' in bridge else 1.12
            elif close == '>' and '/' in bridge:
                value *= 2.34
        before, after = s[:match.start()], s[match.end():]
        if any(c in OPEN for c in before):
            value *= 0.35
        elif any(c in CLOSE for c in before):
            value *= 0.75
        if i == j and close == '>' and after.startswith('/'):
            value *= 0.28  # A closing HTML tag is weaker than a new tag.
        if i == j and close == ']' and after.startswith(']'):
            value *= 0.25  # A completed empty square group.
        if '\n' in token and i != j:
            value *= 0.65
        return value
    if s in ('(', '（'):
        if '\n' in token:
            return 0.06
        return 0.56 if token.startswith(' ') else 0.48
    if s == '(\\':
        return 0.63
    if s.endswith('(') and s[:-1] in (
        '!', '^', '__', '/', '*', '.', '+', '-'
    ):
        return 0.45
    if s in ('([', '({', '[(', '[{'):
        return -0.30
    if s in ('_{', '^{'):
        return 0.30
    if s in ('","', "','", "':'", '":"'):
        return 1.15
    return 0.0


def step(carry, prefix, upstream):
    return None, float(response(prefix.token_strings[-1]))

programs.haiku:
"""Bracket-junction detector for layer-0 MLP component 3613.

Fires on a token that closes one bracket and opens another with nothing
between them, such as "][", "}{", ")(", "](", "){", and on a plain "(".
The strength depends on the pair of brackets, most of all "][" and "}{".
"""

READS = ()

CLOSERS = ")]}>"
OPENERS = "([{<"

# typical activation for each closer-then-opener pair, read off the data
JUNCTION = {
    "][": 6.7, "}{": 4.8, ")(": 4.3, ")[": 2.4, "](": 2.2, "}(": 2.1,
    "><": 2.1, "]{": 2.0, "){": 1.4, "}[": 1.3, ">{": 1.2, ">(": 0.9,
}
PLAIN_PAREN = 0.55   # a lone "(" or " (" token
OTHER_JUNCTION = 1.0  # any other closer-then-opener pair


def junction(token):
    """The first closer followed later by an opener, as a two-character pair."""
    for i, c in enumerate(token):
        if c in CLOSERS:
            for d in token[i + 1:]:
                if d in OPENERS:
                    return c + d
    return None


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    pair = junction(token)
    if pair is not None:
        return None, JUNCTION.get(pair, OTHER_JUNCTION)
