        return None, 0.001
    if token == '\t ':
        return None, -0.39
    if token.startswith('\t') and not stripped and len(token) > 1:
        return None, -0.014
    if lower == '_':
        return None, -0.52 if token.startswith(' ') else -0.14
    if lower in ('._', '/_', '(_'):
        return None, -0.46
    if lower and set(lower) == {'_'}:
        return None, 0.044
    if word == 'shall':
        return None, -1.06
    if word.startswith('therm'):
        return None, -0.81

    if word.startswith('ch'):
        if word.startswith(('check', 'character', 'chapter', 'church',
                            'children', 'chinese', 'china', 'christmas')):
            return None, -0.082
        if word.startswith(('chang', 'charg', 'challeng', 'choic', 'cheese')):
            return None, -0.27
        value = -0.70
    elif word.startswith('sh'):
        if word.startswith(('show', 'short', 'shift', 'shape', 'sheet',
                            'shot', 'shoot', 'ship', 'shoulder', 'shelter')):
            return None, -0.078
        value = -0.67
    elif word.startswith('th'):
        if word.startswith(('think', 'thought', 'thank', 'three', 'third',
                            'theor', 'theorem', 'thirty', 'theta',
                            'thread', 'throw')):
            return None, -0.043
        value = -0.35
    elif word.startswith('ph'):
        if word.startswith(('phase', 'photo', 'physi', 'phenomen', 'phere')):
            return None, -0.10
        value = -0.46
    elif word.startswith('sch'):
        weak = word == 'sch' or word.startswith(('school', 'sched'))
        return None, -0.014 if weak else -0.53
    elif word.startswith('h'):
        weak = len(word) < 2 or word.startswith((
            'http', 'head', 'high', 'help', 'hist', 'hand', 'hosp',
            'home', 'house', 'health', 'hope', 'human', 'happy', 'heart'))
        return None, 0.026 if weak else -0.10
    elif word.startswith(('ч', 'ш', 'щ')):
        return None, -0.22
    elif word.startswith('ش'):
        return None, -0.35
    elif word.startswith(('しゃ', 'しゅ', 'しょ', 'シャ', 'シュ', 'ショ',
                          'シェ', 'ちゃ', 'ちゅ', 'ちょ', 'チャ', 'チュ', 'チョ')):
        return None, -0.67
    elif word.startswith(('し', 'ち', 'シ', 'チ')):
        return None, -0.15
    else:
        return None, 0.0025

    # Shared adjustments to the four main h-digraph families.
    length = len(stripped)
    if length <= 3:
        value += 0.26
    elif length == 4:
        value -= 0.11
    elif length >= 8:
        value += 0.055
    if stripped[:1].isupper():
        value -= 0.17
    if stripped.isupper():
        value += 0.13
    if not token.startswith(' '):
        value += 0.10
    if lower.endswith(('s', 'ed', 'ing')):
        value += 0.11
    return None, float(value)

