def fused_caret(text):
    if text.startswith('^{'):
        return 0.16 if '-' in text else 0.57
    if text.startswith(('(^', '.^')):
        return 2.6
    if text.startswith(')'):
        return 1.4
    if text.startswith(('_', '|')):
        return 1.05
    if text.startswith(('^(', '^-')):
        return 1.15
    if len(text) > 1 and text[0] == '^' and text[1].isalpha():
        return 0.7 if text[1].islower() else 1.2
    if text.count('^') > 1:
        return 1.3 if len(text) == 2 else 0.93
    return 1.6


