    doc = prefix.document_ids[-1]
    count, position = (0, 0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    text = token.strip()
    value = 0.0
    if '^' in text:
        if text != '^':
            value = fused_caret(text)
        elif '\n' in token:
            value = 1.49
        elif position == 0:
            value = 1.75
        else:
            value = 2.35 - 0.086 * math.log1p(count) - 0.038 * math.log1p(position)
            if token.startswith(' '):
