            previous = prefix.token_strings[-2]
            base = previous.strip()
            if base and base[-1] in ')}]':
                value -= 0.47
            elif base and base[-1].isdigit():
                value -= 0.13
            elif len(base) == 1 and base.isascii() and base.isalpha():
                value -= 0.25 if base.islower() else 0.11
            elif '\n' in previous:
                value += 0.23
        count += 1
