            value = max(0.45, 1.35 - 0.3 * math.log2(len(text)))
            if len(text) == 1:
                value = 1.98 if position == 0 else 1.26 if token.startswith(' ') else 1.35
        else:
            value = 0.8 if '/' in text else 1.1
