PRONOUNS = set('i you he she it we they me us them my your his her our their'.split())
PREPOSITIONS = set('of to in on at by for from with as into'.split())
PUNCTUATION = {'.': 0.24, ',': 0.172, ':': 0.095, ';': 0.025}


def continuation_byte(token_id):
    return token_id < 256 and 0x80 <= BYTE_VALUES[token_id] < 0xC0


