        if continuation_byte(token_id):
            return -1.02
        if token_id < 256:
            return -3.5 if BYTE_VALUES[token_id] < 0xE0 else -2.65
        return -2.2
    if s.startswith('<|'):
        return -0.40
    if s == '#':
        return 0.93
    if not w:
        return -0.29 if len(s) == 1 else -0.15
    if w.isdigit():
        return 0.256 if w == '1' else 0.12
    if s.isascii() and len(s) == 1 and s.isalpha():
        return 0.335 if s.isupper() else 0.428
    if s.startswith(' '):
        if w in {'the', 'The'}:
            return -0.682
        if w in {'an', 'An'}:
            return -0.743
        if w in {'a', 'A'}:
            return -0.167
        if w.lower() in AUXILIARIES:
            return -0.402
        if w.lower() in PRONOUNS or w.lower() in PREPOSITIONS:
            return -0.29
        if w.isalpha():
