"""Approximate a local spelling-transition response.

The strongest positive response is to an r/l-starting token following an
I/Y-like vowel ending. Unbroken word pieces respond much more strongly than
space-separated words. U-like endings give a weaker response, other vowels
a smaller one. Short w/h/n/i pieces give smaller responses; long pieces
are attenuated. The same broad letter/syllable categories are recognized in several alphabets.
A single l after a longer y-ending piece (as in chemical -yl endings)
has a stronger response. Initial I/i in Latin or Cyrillic also responds.
Latin I and 1 following a high-vowel ending get smaller positive responses.
Liquids one character into a piece have a smaller response after high vowels.
The familiar phrase I see is an explicit negative exception. NUL separators
are ignored when remembering the previous spelling piece.
"""
import unicodedata as ud

READS = ()

# The standard order of the 21 vowels encoded in Hangul syllables.
HANGUL_VOWELS = "ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ"


def plain(c):
    """Lowercase and fold accents and compatibility/fullwidth forms."""
    return ''.join(x for x in ud.normalize('NFKD', c.lower())
                   if not ud.combining(x))


def ending(s):
    """Classify the final character or open syllable of a spelling piece."""
    c = next((c for c in reversed(s) if not ud.combining(c)), '')
    if not c:
        return ''
    normalized = plain(c)
    if (normalized in ('i', 'y', 'j', 'ı', 'ɪ')
            or normalized in 'иыіιυηیيი' or c in 'ิี'):
        return 'high'
    if normalized == 'u' or normalized in 'ую' or c in 'ุู':
        return 'u'
    if c in ('いきぎしじちぢにひびぴみりぃ'
             'イキギシジチヂニヒビピミリィ'):
        return 'high'
    if c in ('うくぐすずつづぬふぶぷむゆる'
             'ウクグスズツヅヌフブプムユル'):
        return 'u'
    # Hangul stores 19 onsets x 21 vowels x 28 possible final consonants.
    if '가' <= c <= '힣' and (ord(c)-0xac00) % 28 == 0:
        vowel = HANGUL_VOWELS[((ord(c)-0xac00)//28) % 21]
        if vowel in 'ㅑㅒㅕㅖㅟㅢㅣ':
            return 'high'
        if vowel in 'ㅜㅠㅡ':
            return 'u'
    return ''


def is_liquid(c):
    """R/L letters, or syllables beginning with an R/L consonant."""
    if not c:
        return False
    return (plain(c) in ('r', 'l', 'ł') or c.lower() in 'рлρλرلლრ'
            or c in 'らりるれろラリルレロรล'
            or ('가' <= c <= '힣' and (ord(c)-0xac00)//588 == 5))  # Hangul ㄹ.


def response(previous, token):
    clean = token.strip()
    size = len(clean)
    if not size:
        return -0.002
    before = ending(previous)
    initial = clean[0]
    space = token[0].isspace()
    if not previous and clean in ('I', 'i', 'И', 'и'):
        return 2.09 if clean == 'I' and not space else 1.05
    if before not in ('high', 'u'):
        # Other vowel endings have a much weaker liquid response.
        if previous and is_liquid(initial) and not space and size <= 3:
            last = previous[-1].lower()
            base = plain(last)
            if last in 'öæ':
                return 0.45
            if base in ('e', 'o', 'a'):
                if last == 'a':
                    return 0.03
                return 0.16 if last.isascii() else 0.28
        return -0.002
    if previous.strip() == 'I' and clean == 'see':
        return -0.75
    if is_liquid(initial):
        if before == 'u':
            if space:
                return 0.03
            if 'KATAKANA' in ud.name(initial, ''):
                return -0.05
            if 'HIRAGANA' in ud.name(initial, ''):
                return 0.14
            if previous and 'HANGUL' in ud.name(previous[-1], ''):
                return 0.06
            return 0.79 if size <= 3 else 0.30
        if space:
            if plain(previous[-1:]) == 'i':
                return 0.35 if size <= 4 else 0.13
            return 0.24 if size <= 2 else 0.04
        if size <= 3:
            if previous and 'HIRAGANA' in ud.name(previous[-1], ''):
                return 0.38
            if 'HANGUL' in ud.name(initial, ''):
                return 0.73
            if (clean == 'l' and plain(previous[-1:]) == 'y'
                    and len(previous.strip()) >= 3):
                return 2.5  # Chemical-style -yl endings.
            if size <= 2:
                return 1.95 if previous.strip().isupper() else 1.70
            return 1.44 if len(previous.strip()) <= 3 else 0.76
        if size <= 5 and len(previous.strip()) <= 4:
            return 0.94
        return 0.29
    if before == 'u':
        return 0.002
    # A liquid can be preceded by a vowel or punctuation inside this piece.
    if not space and 2 <= size <= 5 and is_liquid(clean[1]):
        first = plain(initial)
        if first in ('a', 'e', 'i', 'o', 'u'):
            return 0.4 if size <= 3 else 0.2
        if initial in '-./_':
            return 0.65 if size == 2 else 0.2
    if clean == 'I':
        return 0.68 if not space else 0.13
    if clean == '1':
        return 0.22
    if size <= 2:
        letter = plain(initial)
        if letter == 'w':
            return 0.06 if space else 0.71
        if letter == 'h':
            return 0.04 if space else 0.41
        if letter == 'i':
            return 0.04 if space else 0.31
        if letter == 'n' or initial == 'н':
            return 0.03 if space else 0.26
        return 0.005
    return -0.018


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = float(response(previous, token))
    # NUL separators occur in misdecoded UTF-16 text: keep the last letter.
    remembered = previous if token == '\x00' else token
    return (doc, remembered), value

