    'a': (-0.01, 2.38, 0.15),
    'e': (-0.07, 1.78, 0.11),
    'i': (-0.22, 1.87, 0.40),
    'o': (0.08, 3.29, -0.08),
    'u': (-0.09, 3.15, 0.39),
    'y': (0.04, 1.18, 0.34),
