    # document-initial response, and strength as the next token's cue.
    if not count:
        return 0.0004, 0.0, -0.004, 0.0
    if n == 1:
        base, gain, first, previous = 0.017, 0.53, 0.8, 1.0
        if space:
            base, gain, first = 0.008, 0.38, 0.99
        if token == 'I':
            first = 1.34
        elif token == 'i':
            first = 0.86
    elif n == count:
        # Repeated i's often spell Roman numerals, not repeated vowels.
        base, gain, first, previous = 0.027, 0.40, 0.44, 0.06
        if space:
            base, gain = -0.054, 0.14
    elif ending and n <= 4:
        if n == 2:
            base, gain, first, previous = -0.045, 0.58, 0.39, 0.78
        else:
            base, gain, first, previous = 0.026, 0.43, 0.29, 0.63
        if space:
            base, gain, first = 0.005, gain * 0.24, first * 0.33
    elif ending:
        base, gain, first, previous = 0.01, 0.03, 0.05, 0.20
    else:
        if n <= 4:
            base, gain, first = -0.008, 0.22, 0.03
        else:
            base, gain, first = 0.002, 0.09, -0.01
        previous = 0.28 if n <= 2 else 0.16 if n <= 4 else 0.055
        if space:
            base, gain = 0.0, gain * 0.22
            first = 0.02 if n <= 4 else -0.008
    if space and letters in FUNCTION_WORDS:
        previous = 0.12
    return base, gain, first, previous


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    base, gain, first, previous = describe(token)
    if carry is None or carry[0] != doc:
        value = first
    else:
        value = base + gain * carry[1]
        if carry[2] == 'war' and token.strip() in ('I', 'II'):
            value = -0.39 if token.strip() == 'I' else -0.58
    return (doc, previous, token.strip().casefold()), float(value)

