"""A lexical 'with' signal, strongest outside conventional '... with' phrases.

Relational word families ('agree with', 'compatible with') suppress it;
companions and materials ('work with', 'fill with') give intermediate values.
Capitalized 'With' and comma-separated 'with' are particularly strong.
Small secondary signals cover translations, spelling relatives, and sentence
openers without punctuation. This is a word-family heuristic, not a parser.
"""
import re

READS = ()

# Prefixes group ordinary English word families, including their inflections.
RELATIONAL = tuple('''
agree disagree compar contrast compat incompat compli consist inconsisten
conflict contact coincid collid clash align affiliat connect conjunc
interact interfer intersect interface communic collabor cooper correl
relat partner confront reconcil deal cope coping struggl acquaint
obsess confus synonym accordance along border consult conversat
'''.split())
COMPANION_OR_MATERIAL = tuple('''
work talk chat speak discuss negotiat interview diagnos equip arm comb
mix replac fill provid help assist match shar play involv satisf
pleas comfort lov troubl issue experiment integrat merg together
'''.split())
APPLICATION = tuple('''
load suppl infect charg cover stain incubat treat inject reinforc label
supplement endow start begin proceed end line problem patient
'''.split())
TRANSLATIONS = {'con': 0.38, 'com': 0.20, 'mit': 0.24,
                'avec': 0.48, 'với': 0.35, 'dengan': 0.32}


def with_value(previous, history):
    if previous == 'familiar':
        return -0.34
    if previous.startswith(('associat', 'engag')):
        return -0.17
    if previous.startswith(RELATIONAL):
        return 0.12
    if previous == 'working':
        return 0.29
    if previous.startswith(COMPANION_OR_MATERIAL):
        return 0.58
    if previous.startswith(APPLICATION):
        return 0.89
    if history.rstrip().endswith(','):
        return 1.55
    if previous in {'but', 'and', 'even', 'especially', 'or', 'as'}:
        return 1.44
    if previous in {'up', 'down', 'me', 'you', 'us', 'them'}:
        return 0.72
    return 1.13


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    core = word.strip('_-.\"\'()[]')
    value = 0.0
    if core.lower() == 'with':
        match = re.search(r'([A-Za-z]+)\s*$', history)
        previous = match[1].lower() if match else ''
        if core != word:
            value = 1.24
        elif word == 'With':
            value = 1.58
        elif word == 'WITH':
            value = 1.0
        elif not token.startswith(' '):
            value = 1.32
        else:
            value = with_value(previous, history)
    elif token.startswith(' ') and word in TRANSLATIONS:
        value = TRANSLATIONS[word]
    elif token.startswith(' ') and word in {'The', 'This', 'They', 'It'}:
        value = 0.30 if re.search(r'[A-Za-z]\s*$', history) else 0.03
    elif word in {'ith', 'width'}:
        value = 0.25
    elif word == 'within':
        value = 0.08
    elif token.startswith(' ') and word == 'without':
        value = -0.05
    return (doc, (history + token)[-100:]), float(value)

