"""layers.0.mlp.down_proj:3633 -- the "with" detector.

This component fires on the English preposition "with" (and its spelling variants
"With", "WITH", "_with", "-with") and weakly on the same word in other languages
("avec", "con", "com", "mit", "dengan", "với"). Its activation is large (about 1) when
"with" opens a free-standing phrase, e.g. "..., with the bullet", "...finished with",
"...called with", and near zero when "with" completes a fixed pairing such as
"familiar with", "associated with", "dealing with", "compared with".

Prediction, per token: 1.0 on "with"-words, 0.0 on "with"-words right after a fixed
pairing word, 1.5 on "with" after a comma/"and"/"but", 0.5 on the foreign-language
equivalents, 0 elsewhere. Only the previous token is read, so it is causal.
"""

WITH_WORDS = {" with", " With", "With", "with", " WITH", "WITH", "_with", ".With", "-with", "(with"}
FOREIGN_WITH = {" avec", " Avec", " con", " com", " mit", " dengan", " với"}
# Words after which "with" is a fixed pairing (its activation is about zero).
FIXED_PAIRING = {
    " familiar", " associated", " dealing", " compared", " interacting", " interact",
    " consistent", " compliance", " comply", " contact", " connected", " connection",
    " association", " accordance", " correlated", " partnering", " deal", " working",
}
CLAUSE_BREAK = {",", " and", " but"}

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if token in WITH_WORDS:
        if before in FIXED_PAIRING:
            return None, 0.0
        if before in CLAUSE_BREAK:
            return None, 1.5
        return None, 1.0
    if token in FOREIGN_WITH:
        return None, 0.5
    return None, 0.0

