READS = ()

STRAIN = frozenset('''
    worry worried worrying distress anxious cry crying tears fatigue exhaustion
    fragile recuper
'''.split())
HEALTH = frozenset('''
    obesity overweight hospital nurse pregnancy hormones hungry hurt
'''.split())
