def background(token):
    word = token.strip()
    value = 0.003 - 0.00086 * min(len(word), 20)
    if token.startswith(' '):
        value -= 0.0021
    if any('\u4e00' <= c <= '\u9fff' for c in word):
        value -= 0.0049
    if any('\u0400' <= c <= '\u052f' for c in word):
        value -= 0.0037
    if word and not any(c.isalnum() for c in word):
        value -= 0.0014
    if word.isascii() and word.isalpha() and len(word) > 4:
        if word.endswith('ing'):
            value -= 0.0098
        if word.endswith(('ness', 'ity', 'ities', 'tions')):
            value -= 0.0129
        if word.endswith(('ic', 'al')):
            value += 0.0122
