# Chinese mass/quality and assets.
MASS_OR_ASSET_WORDS = {'质量', '質量', '资产', '資產'}


def lexical_value(token):
    word = token.lstrip(' \t\r\n_-.(')
    w = word.lower()
    spaced = token.startswith(' ')
    if w == 'ass':
        if token.startswith('-'):
            return -6.2
        if word.isupper():
            return -5.4 if spaced else -4.8
        if word[:1].isupper():
            return -5.0 if spaced else -3.5
        return -4.45 if spaced else -4.25
    if w == 'mass':
        return -4.3 if word[:1].isupper() else -3.75
    if w == 'masses':
        return -2.7
    if w.startswith(('massiv', 'massag', 'biomass')):
        return -0.85
    if w.startswith('assist'):
        if w == 'assistant' and token == word:
            return -1.9
        if w.startswith('assistan'):
            return -2.3 if w == 'assistant' else -1.8
        return -2.6
    if w.startswith('assess'):
        return -1.05 if w.startswith('assessment') else -1.35
    if w == 'pass':
        return -1.5 if spaced or word.isupper() else -2.3
    if w.startswith('pass') and not w.startswith('password'):
        return -0.85 if w.startswith(('passag', 'passion')) else -1.2
    if w.startswith(('associ', 'assign', 'assum', 'asset', 'assur', 'accessor')):
        return -0.6
    if w.startswith('assass'):
        return -2.8
    if w.startswith('assay'):
        return -2.6
    if w.startswith('ass') and len(w) <= 6 and w not in ('assert', 'assez'):
        return -2.2
    if w in ('glass', 'grass', 'compass'):
        return -1.1 if w == 'glass' else -0.55
    if w == 'dass':
        return -0.4
    if w.endswith('ass') and len(w) <= 5 and w != 'class':
        return -1.8
    # Cyrillic ass, mass and rass fragments.
    if w in ('асс', 'масс', 'расс'):
        return -1.6 if w == 'расс' else -3.0
    if w in ('iss', 'oss', 'diss'):
        return -0.5
    if w.startswith('business'):
        return -0.3
    if word in ASSISTANCE_WORDS or word in MASS_OR_ASSET_WORDS:
        return -1.0
    # Simplified/traditional Chinese 'assist'.
    if word in ('协助', '協助'):
        return -1.9
    return 0.0


def context_value(previous, token):
    stem = previous.lstrip(' \t\r\n_-.(').lower()
    if stem == 'mass' and token == ' of':
        return -0.95
    if stem == 'ass':
        tail = token.lower()
        if tail.startswith(('ist', 'ay')):
            return -1.65
        if tail.startswith('ess'):
            return -0.5 if tail.startswith('essment') else -1.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = lexical_value(token) + context_value(previous, token)
    return (doc, token), float(value)

