programs.sol:
"""Approximate a TeX typesetting response, strongest at displayed mathematics.

Recognize display delimiters, font/layout commands, and equation environments,
including split control words and braced command arguments. Mathematical values
and ordinary prose receive zero. Only a short text tail is retained within each
document.
"""
import re

READS = ()
LAYOUT = {
    'display': -2.6, 'displaystyle': -5.6, 'textstyle': -2.4,
    'math': -0.3, 'mathbb': -0.6, 'mathcal': -0.6, 'mathrm': -0.35,
    'text': -0.4, 'textr': -1.75, 'left': -0.7, 'boxed': -1.15,
    'quad': -1.7, 'qquad': -1.8, 'eq': -2.1, 'frac': 0.2,
}
ARGUMENT = {
    'frac': -1.1, 'mathrm': -1.55, 'text': -1.2, 'sqrt': -0.62,
    'begin': -1.3, 'end': -0.75, 'mathbb': -1.25, 'mathcal': -1.2,
}
# Responses at opening name, closing name, and opening header's final brace.
ENVIRONMENT = {
    'align': (-6.0, -1.4, -2.8), 'aligned': (-4.55, -0.9, -2.2),
    'equ': (-2.9, -0.2, -2.3), 'equation': (-4.3, -0.15, -2.3),
    'array': (-2.0, -0.3, -1.6), 'cases': (-2.95, -0.58, -1.2),
    'split': (-4.0, -0.65, -2.2), 'gather': (-4.3, -0.75, -3.0),
    'eq': (-4.4, -1.0, -2.5), 'eqnarray': (-3.8, -0.87, -2.5),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    s = token.strip(' ')
    value = {'{': -0.9, '{\\': -0.55, '{{': -0.46,
             '^{': -0.23, '_{': -0.21}.get(token, 0.0)
    if s == '$$':
        value = -1.5
    elif s in ('\\(', '\\['):
        value = -1.2 if '(' in s else -1.75
    elif '\\\\' in s and not any(c.isalpha() for c in s):
        value = -1.15
    elif tail.endswith('\\') and s.startswith('['):
        value = -1.3
    if s == '\\' and tail.rstrip().endswith('$$'):
        value = -2.55
    if token in ('\n', '\n\n') and tail.rstrip().endswith('$$'):
        value = -2.15 if token == '\n' else -0.8

    command = re.search(r'\\([a-z]+)$', tail + token)
    if command and token.isalpha():
        value = LAYOUT.get(command[1], value)
        before = (tail + token)[:command.start()]
        if command[1] in ('display', 'displaystyle'):
            if not before.endswith(('$', '{')):
                value = -1.3 if command[1] == 'display' else -4.05
    before_brace = re.search(r'\\([a-z]+)$', tail)
    if token == '{' and not before_brace:
        if tail.rstrip().endswith(('^', '_', '{')):
            value = -0.7
        elif tail.endswith('}'):
            value = -0.3
        elif not tail.endswith('\\'):
            value = -0.25
    if s == '{' and before_brace:
        value = ARGUMENT.get(before_brace[1], -0.9)
    if token == 'eq' and re.search(r'\\label\{$', tail):
        value = -1.65
    env = re.search(r'(?:\\)?(begin|end)\{([a-z]*)$', tail)
    if env and env[2] + token in ENVIRONMENT:
        value = ENVIRONMENT[env[2] + token][env[1] == 'end']
    header = re.search(r'(?:\\)?begin\{([a-z]+)\*?$', tail)
    if header and header[1] in ENVIRONMENT:
        if token in ('}', '}\\', '}\n', '}\r\n', '*'):
            value = -1.5 if token == '*' else ENVIRONMENT[header[1]][2]
    return (doc, (tail + token)[-64:]), float(value)

