"""Layer-0 MLP down-projection component 3641: a LaTeX-markup detector.

The component writes a negative signal into the residual stream whenever the
model reads LaTeX math markup: the style word of \\displaystyle, math delimiters
($$, \\(, \\[, \\\\), LaTeX command names after a backslash (\\quad, \\align,
\\left, \\text, \\bb...), and the opening brace of a command argument (\\text{,
\\mathbb{). Ordinary text, and the positive-leaning \\frac, stay near zero.
"""

READS = ()

STYLE_WORDS = {"display", "style"}
COMMAND_WORDS = {"quad", "align", "left", "right", "text", "bb", "cal", "eq", "begin", "end"}
DELIMS = {"$$", "\\(", "\\[", "\\\\", "]\\\\"}
OPEN_BRACES = {"{", "{\\", "["}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    recent = [s.strip() for s in prefix.token_strings[-3:-1]]
    after_cmd = any(s.endswith("\\") for s in recent)
    if tok in STYLE_WORDS and after_cmd:
        value = -3.0
    elif tok in DELIMS:
        value = -1.3
    elif tok in COMMAND_WORDS and after_cmd:
        value = -1.0
    elif tok in OPEN_BRACES and (after_cmd or (recent and recent[-1] in COMMAND_WORDS)):
        value = -1.0
    else:
        value = 0.0
    return carry, float(value)

