"""Predict negative responses to rare mathematical typesetting syntax.

In the harvested examples, the strongest responses cluster around TeX math
commands and their delimiters. This recognizes those local patterns, rather
than trying to reproduce the model's hidden computation.
"""
READS = ()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    i = len(tokens) - 1
    token = tokens[i]
    recent = tokens[max(0, i - 5):i]
    near = ''.join(recent[-3:])
    context = ''.join(recent)
    has_command = '\\' in near

    if token == 'style' and 'display' in context[-18:]:
        return None, -4.5
    if token == 'align' and '\\end{' in context:
        return None, -1.5
    if token == 'quad' and has_command:
        return None, -1.7
    if token == 'left' and has_command:
        return None, -0.9
    if token == 'cal' and 'math' in context[-12:]:
        return None, -0.7
    if token == '{' and has_command:
        return None, -1.0
    if token in ('\\[', '\\('):
        return None, -0.9
    if token == '[' and has_command:
        return None, -1.0
    if token in ('\\\\', ' \\\\'):
        return None, -0.8
    if token == ' $$':
        return None, -1.2
    if token == '^{' and '$' in context[-8:]:
        return None, -0.5
    return None, 0.0

