READS = ()

# Spaced lowercase, spaced capital, unspaced word, word-internal fragment.
POSSESSIVES = {
    'its': (6.55, 6.53, 4.97, 1.28),
    'his': (1.73, 1.49, 1.30, 1.13),
    'their': (1.67, 1.49, 1.48, 1.40),
    'her': (1.38, 1.24, 1.01, 0.63),
    'my': (1.18, 0.95, 0.66, 0.43),
    'your': (1.00, 0.71, 0.45, 0.30),
    'our': (0.88, 0.59, 0.69, 0.27),
    'whose': (1.01, 0.80, 0.65, 0.40),
    'thy': (0.67, 0.50, 0.40, 0.40),
}
CONTRACTION_HOSTS = {
    'it', 'he', 'she', 'that', 'there', 'what', 'who', 'where',
    'here', 'how', 'when', 'why', 'let',
}
IRREGULAR_PLURALS = {'men', 'women', 'children', 'people'}
CLAUSE_OPENERS = {
    'if', 'that', 'because', 'unless', 'whether', 'as', 'before', 'after',
}
TIME_PLACE_OPENERS = {'when', 'where', 'since'}
BE_HAVE_DO_FORMS = {
    'is', 'was', 'are', 'were', 'has', 'have', 'had', 'do', 'did', 'done', 'does',
}
TRANSITIVE_VERBS = {
    'make', 'made', 'makes', 'making', 'get', 'got', 'getting',
    'take', 'took', 'taking', 'use', 'used', 'using', 'put', 'puts',
    'see', 'saw', 'seen', 'think', 'thought', 'call', 'called',
    'read', 'write', 'wrote', 'find', 'found', 'say', 'said',
    'give', 'gave', 'given',
}
OTHER_POSSESSIVES = {
    'его': 1.52,
    'ее': 1.40,
    'её': 1.68,
    'их': 0.36,
    'su': 0.58,
    'sus': 0.84,
    'sua': 0.88,
    'suas': 0.80,
    'suo': 0.71,
    'suoi': 1.00,
    'seu': 0.73,
    'seus': 1.00,
    'sa': 0.27,
    'ses': 0.53,
    'leurs': 0.56,
}
# German case endings, relative to the feminine/plural form.
GERMAN_CASES = {'e': 0.0, 'er': 0.2, 'en': -0.12, 'em': -0.30, 'es': 0.0}
CHINESE_REFERENCE = {
    '其': 1.50,
    '它': 1.65,
    '它的': 2.62,
    '它们': 0.83,
    '它是': 1.00,
    '自己': -0.65,
    '自己的': -0.48,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.lower()
    host = previous.strip().lower()
    spaced = token[:1].isspace()
    last_char = previous[-1:]
    internal = not spaced and last_char.isascii() and last_char.isalpha()
    capital = raw[:1].isupper()
    value = 0.0
    if word in POSSESSIVES:
        lower, title, boundary, fragment = POSSESSIVES[word]
        if spaced:
            value = title if capital else lower
        elif internal:
            value = fragment
        else:
            value = 0.9 * title if capital else boundary
        if raw.isupper() and spaced:
            if word == 'its':
                value *= 0.8
            elif word in {'her', 'my', 'your'}:
                value *= 0.6
    elif word == 'it':
        if raw.isupper():
            value = 0.28 if internal else 1.45
        elif capital:
            value = 1.9 if internal else 2.78 if spaced else 2.37
            if first:
                value *= 0.72
        elif internal:
            value = 0.21
        elif not spaced:
            value = 1.63
        elif first:
            value = 1.63
        elif host in TIME_PLACE_OPENERS:
            value = 3.12
        elif host in CLAUSE_OPENERS:
            value = 2.79
        elif host in BE_HAVE_DO_FORMS:
            value = 1.89
        elif host in TRANSITIVE_VERBS:
            value = 2.11
        else:
            value = 2.39
    elif word == 'itself':
        value = 2.37
    elif raw.lstrip('.,—…-_"“\'') in {'it', 'It', 'IT'}:
        value = 1.9
    elif word in {"'s", '’s'}:
        value = 0.0 if host in CONTRACTION_HOSTS else (
            0.23 if host in IRREGULAR_PLURALS else 0.89)
    elif spaced and word in OTHER_POSSESSIVES:
        value = OTHER_POSSESSIVES[word] * (0.8 if capital else 1.0)
    elif spaced and word[:4] == 'sein' and word[4:] in GERMAN_CASES:
        value = 1.63 + GERMAN_CASES[word[4:]]
    elif spaced and word[:3] == 'ihr' and word[3:] in GERMAN_CASES:
        value = 1.16 + GERMAN_CASES[word[3:]]
    elif word in CHINESE_REFERENCE:
        value = CHINESE_REFERENCE[word]
    elif word[-1:] in {'其', '它'}:
        if word[:-1] in {'将', '使', '对', '把', '为', '在', '以', '但', '让'}:
            value = 2.55
        elif word[:-1] in {'及', '与', '因', '因为'}:
            value = 3.3
    if first and word in POSSESSIVES:
        value *= 0.94 if word == 'its' else 0.70
    return (doc, token), float(value)

