"""Predict the component from a few tokenized pronoun and possessive forms.

Its clearest signal is “its”, especially at the start of a word. “It” and
other possessive forms give smaller signals; a bare “it” piece gets little.
"""
READS = ()

_ITS = {" its", " Its", "Its"}
_IT = {" it", " It", "It", " itself"}
_POSSESSIVE = {" his", " His", " their", " Their", " her", " Her"}
_SMALL_POSSESSIVE = {" my", " My", " your", " Your", " our", " Our"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in _ITS:
        return None, 6.5
    if token == " It":
        return None, 2.8
    if token in _IT:
        return None, 2.4
    if token == "it":
        return None, 0.5
    if token == "its":
        return None, 1.45
    if token in _POSSESSIVE:
        if token in {" her", " Her"}:
            return None, 1.35
        return None, 1.6
    if token in _SMALL_POSSESSIVE:
        if token in {" my", " My"}:
            return None, 1.1
        if token in {" our", " Our"}:
            return None, 0.8
        return None, 0.9
    if token in {"'s", "’s"}:
        return None, 0.55
    if token == " whose":
        return None, 1.0
    if token in {" его", " ее"}:
        return None, 1.4
    if token in {"其", " 它", "它的", "及其"}:
        return None, 1.5
    return None, 0.0

programs.sol:
"""A token-level typography detector, plus a few demonstrative/quantifier responses.

Space/tab padding and repeated visual-divider characters get positive values;
ordinary short gaps stay near zero. Run length, included newlines, and the
preceding line ending calibrate the response. The length responses are not
monotone: indentation-sized runs behave differently from other padding.
"""
from collections import Counter

READS = ()

# Calibrations indexed by the number of spaces, not by vocabulary identifiers.
SPACE_MIDLINE = (0., -.004, -.11, -.11, .76, .99, 1.24,
                 .71, 1.20, 1.18, 1.12, .55, .92)
SPACE_AFTER_NEWLINE = (0., -.087, -.056, -.047, 1.05, 1.05, 1.42,
                       .66, 1.59, 1.31, 1.41, .67, 1.37)
SPACE_WITH_NEWLINE = (0., .034, -.014, .11, .29, .78, .81,
                     .92, .71, 1.08, 1.06, 1.02, .76)
TAB_THEN_SPACES = (0., -.15, .18, -.12, .62, .71,
                   .70, .36, .73, .60, .90, .23)


def space_response(n, at_start):
    if n <= 12:
        return (SPACE_AFTER_NEWLINE if at_start else SPACE_MIDLINE)[n]
    # Longer runs are approximated using their size modulo four.
    if at_start:
        return (1.57, 1.20, 1.40, .45 + .014 * min(n, 40))[n % 4]
    return max(.25, (1.0, .82, .90, .55)[n % 4] - .008 * min(n, 40))


def whitespace_response(s, at_start):
    if s == '\x0c':
        return .35
    if '\xa0' in s:
        n = s.count('\xa0')
        if ' ' in s:
            return min(1.60, .49 + .58 * (n - 1))
        return (0., -.02, .03, .08, .75, .80, .82, .82, 1.02)[min(n, 8)]
    gap = max(s.replace('\r', '').split('\n'), key=len)
    ended = '\n' in s
    if '\t' in gap:
        nt, ns = gap.count('\t'), gap.count(' ')
        if ns == 0:
            value = (0., -.05, .63, .76, .94, 1.06)[min(nt, 5)]
        elif nt == 1 and gap.startswith('\t'):
            value = TAB_THEN_SPACES[ns] if ns <= 11 else (
                .90, .66, .80, .47)[ns % 4]
        else:
            value = min(1.4, .55 + .13 * nt + .025 * ns)
        if ended:
            return value - .22 if nt >= 2 else max(0., value * .60)
        return value
    n = len(gap)
    if ended:
        value = SPACE_WITH_NEWLINE[n] if n <= 12 else (
            1.05 if n % 4 else .85)
        if n == 1 and s.count('\n') > 1:
            return 0.0
        return value * (.72 if s.count('\n') > 1 else 1.)
    return space_response(n, at_start)


def divider_response(s):
    core = s.strip()
    if not core:
        return 0.0
    # Allow comment markers around a mostly uniform divider.
    char, n = Counter(core).most_common(1)[0]
    if n < 4 or n < .75 * len(core) or char not in '-=_*/.#~!─':
        return 0.0
    if char in '-=':
        if n <= 16:
            value = (.30, .75, 1.10, 1.23, 1.30, 1.20, 1.25,
                     1.26, 1.38, 1.14, 1.20, 1.23, 1.75)[n - 4]
        elif n == 17:
            value = 1.74
        elif n <= 48:
            value = 1.43
        elif n <= 76:
            value = 1.00 if char == '-' else 1.20
        else:
            value = 1.36
    elif char == '_':
        value = .86 if n >= 48 else min(1.0, .23 + .15 * (n - 4))
    elif char in '.#!':
        value = min(1.35, .13 + .21 * (n - 4))
        if n >= 16:
            value = 1.6 if char == '#' else 1.3
    else:
        value = .90 if char == '─' else min(1.4, .24 + .21 * (n - 4))
    return value * .60 if s.endswith('\n') else value


def indentation_adjustment(s, previous):
    at_start = previous.endswith('\n')
    if s == '\t':
        return .08 if at_start else (.03 if previous.isspace() else -.11)
    if '\n' in s or '\xa0' in s:
        return 0.0
    pure_spaces = s == ' ' * len(s)
    if at_start:
        last = previous.rstrip()[-1:]
        code_ending = bool(last) and last in '{};'
        if pure_spaces and len(s) >= 4:
            if code_ending:
                return -.08
            return .13 if last == ':' else .05
        if pure_spaces:
            if code_ending:
                return -.047
            return .035 if not last or last in '.!?' else 0.0
        if '\t' in s:
            return .025 if code_ending else .10
    elif pure_spaces and previous.isspace() and len(s) >= 4:
        return .15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    if s.isspace():
        value = whitespace_response(s, previous.endswith('\n'))
        value += indentation_adjustment(s, previous)
    else:
        word = s.strip().lower()
        # These lexical responses are distinct from the typography response.
        value = {'those': .78, 'these': .10, 'some': .075,
                 '那些': .41, '那': .23}.get(word)
        if value is None:
            value = divider_response(s)
    return (doc, s), float(value)

programs.haiku:
"""Indentation detector (layer-0 MLP neuron 3643, down_proj direction).

Fires on the whitespace token that indents a line, i.e. a token made only of spaces
and tabs: a run of 4+ spaces, or 2+ tabs, or a mixed run of 8+ characters. It is
strongest right after a line break, weaker mid-line, and weaker for space runs
whose length is 3 mod 4 (7, 11, 15, ...). A whitespace-only line ending in a newline
also fires once it is 6+ spaces wide. It also fires on long ==== / ---- rule lines
and on the word "those". Everything else is predicted as 0.
"""
import re

READS = ()

RULE = re.compile(r"[=\-#/_*~+]{6,}")
WORDS = {" those", " Those", "Those"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if RULE.fullmatch(token.strip()):
        return None, 1.2
    if token in WORDS:
        return None, 0.8
    body = token[:-1] if token.endswith("\n") else token
    if not body or body.strip(" \t "):
        return None, 0.0
    spaces = body.count(" ") + body.count(" ")
    tabs = body.count("\t")
    if spaces and tabs:
        return None, (0.4 if len(body) >= 8 else 0.0)
    after_break = len(prefix) > 1 and "\n" in prefix.token_strings[-2]
    if tabs:
        if tabs < 2:
            return None, 0.0
        return None, (0.8 if after_break else 0.5)
    if spaces < 4:
        return None, 0.0
    if token.endswith("\n"):
        return None, (1.0 if spaces >= 6 else 0.3)
    value = 1.25 if after_break else 0.95
    if spaces % 4 == 3:
        value *= 0.6
    return None, value

