def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token and all(char in " \t\r\n\u00a0" for char in token):
        spaces = token.count(" ") + token.count("\u00a0")
        tabs = token.count("\t")
        if "\u00a0" in token and len(token) >= 4:
            value = 0.13 * len(token)
        elif tabs >= 3:
            value = 0.95
        elif tabs == 2:
            value = 0.52
        elif tabs == 1 and spaces >= 4:
            value = 0.55
        elif spaces >= 4:
            if spaces <= 6:
                value = 0.95
            elif spaces <= 10:
                value = 1.0
            elif spaces <= 14:
