        elif prev in {'first', 'last', 'over', 'more', 'some', 'full',
                      'average', 'response', 'enough', 'much', 'little'}:
            value = -1.0
        elif prev in {'long', 'longer', 'short', 'shorter', 'shortest'}:
            value = -2.3
        elif prev == 'of':
            value = -1.5 if before in DURATION_NOUNS else -0.9
        if token == 'time':
