programs.haiku:
"""Duration detector: a negative response to words for long spans of time (long, duration,
lifetime, permanent...), strongest for 'long' and for the noun that follows a duration word."""

READS = ()

# Words that say something is long-lasting or long in duration.
LONG = {"long", "longer", "longest", "longevity", "lengthy", "prolonged", "prolong", "lasting",
        "longitudinal", "longtime", "durable", "endurance", "enduring", "-long", "-lasting", "elong",
        "länger", "läng", "lange", "longue"}
# Nouns for a span or amount of time.
DURATION = {"duration", "durations", "lifespan", "lifetime", "timespan", "timedelta", "timeframe"}
# Words for something that never ends.
FOREVER = {"permanent", "permanently", "forever", "eternal", "eternity", "indefinitely", "lifelong",
           "everlasting", "perpetual", "immortal", "eternally"}
# Generic time nouns: weakly negative alone, strongly negative after a duration word
# ("long time", "longer period", "long-term").
TIME = {"time", "times", "period", "periods", "span", "spans", "interval", "intervals", "term",
        "timeline", "length", "years", "elapsed", "era", "время", "времени", "시간", "時間", "时间"}
# Short duration words (the contrast end of the same scale).
SHORT = {"short", "shorter", "shortest", "shortly", "brief", "briefly", "shorten"}
# Chinese and Russian words for long time / long duration (久 is the strongest).
CHINESE = {"久": -8.0, "很久": -6.0, "太久": -6.0, "长久": -5.0, "持久": -4.0, "长期": -3.0,
           "不久": -3.0, "永久": -3.0, "年限": -3.0, "期限": -2.4, "长": -1.2, "永远": -1.0,
           "周期": -1.0, "时期": -1.0, "时间": -1.0, "岁月": -0.7}
RUSSIAN = {"давно": -1.6, "долго": -2.0}


def step(carry, prefix, upstream):
    w = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if w in CHINESE:
        return carry, CHINESE[w]
    if w in RUSSIAN:
        return carry, RUSSIAN[w]
    if w in LONG or w in DURATION:
        return carry, -2.7
    if w in FOREVER:
        return carry, -1.2
    if w in SHORT:
        return carry, -0.8
    if w in TIME or w in {"-term", "term"}:
        if prev in LONG or prev in DURATION or prev in SHORT:
            return carry, -2.3
        return carry, -0.5 if w in TIME else 0.0
    if w == "of" and prev in LONG | DURATION:
        return carry, -2.3
    return carry, 0.0

