programs.sol:
"""Colons followed by separators are positive; standalone line ends are negative.

Separator strength depends on whitespace width and punctuation type. A colon
fused with a newline leaves a weaker response on the next indentation.
Line ends are most negative after chat/XML markup, articles, or connectors;
digits and sentence punctuation weaken them. Most other tokens get zero.
This captures the main boundary pattern, not small word-specific fluctuations.
"""
READS = ()
ARTICLES = {'a', 'an', 'the'}
CONNECTORS = {
    'and', 'or', 'but', 'of', 'to', 'for', 'in', 'on', 'at', 'by', 'with',
    'from', 'as', 'into', 'than', 'that', 'which', 'whose', 'his', 'her',
    'their', 'our', 'your', 'its', 'my',
}


def after_colon(token):
    text = token.lstrip()
    if token.isspace():
        if '\xa0' in token:
            return 2.85
        if token == '  ':
            return 2.0
        if '\n' in token or '\r' in token:
            return 1.75
        return 1.44 if len(token) == 1 else 1.55
    if token.startswith(' '):
        if text.startswith(('http', '\\')):
            return 1.4
        if text[:1] in ('(', '[', '<', '$', '%', '«'):
            return 1.05
        if text.startswith('{'):
            return 0.16 if '"' in text else 0.36
        return 0.8 if text and not text[0].isalnum() else -0.08
    if token.startswith('\\'):
        return 1.8
    if token in ('「', '『', '||'):
        return 1.1
    return -0.22 if token.isdigit() else 0.0


def line_end(token, prev):
    if prev.endswith(('.', ';', '?', '。', '？')):
        return 0.0
    if prev.endswith(('!', '！')):
        return 0.25
    if token.startswith(' '):
        if prev and prev[-1].isdigit():
            return -0.33
        return -0.85 if len(token) > 5 or prev.isspace() else -0.6
    if token.startswith('\t'):
        return -0.35
    if prev and prev[-1].isdigit():
        return -0.03
    single = token.count('\n') <= 1
    if prev.endswith('>'):
        return -0.75 if single else -0.56
    word = prev.strip().lower()
    if word in {'assistant', 'user', 'system'}:
        return -0.46
    if single and word in ARTICLES:
        return -0.48
    if single and word in CONNECTORS:
        return -0.36
    if single and not prev.startswith(' ') and prev.isalpha():
        return -0.05 - 0.045 * min(len(prev), 9)
    return -0.2 if single else -0.14


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, older = carry[1:] if carry and carry[0] == doc else ('', '')
    token = prefix.token_strings[-1]
    colon = prev.endswith((':', '：')) and not prev.endswith('::')
    value = 0.0
    if colon:
        value = after_colon(token)
    elif token.isspace():
        if prev.rstrip().endswith((':', '：')):
            value = 0.45
        elif prev.isspace() and older.endswith((':', '：')):
            value = 0.20
        elif '\n' in token or '\r' in token:
            value = line_end(token, prev)
    return (doc, token, prev), float(value)

programs.haiku:
"""Layer-0 MLP down-projection feature #3645, approximated by hand-written rules.

The feature is a 'value-start after a colon' detector with a negative
'line break after a chat tag or a word' component:

* a whitespace token right after a colon (`Posts: 170`, `"key": "value"`,
  `'Joined:' ` ...) fires strongly positive;
* an opening quote or bracket right after a colon fires moderately positive
  (more so after a JSON-style `":`);
* a space right after `=` fires weakly positive;
* a whitespace-only line break is negative: strongly after a chat-template tag
  (`<|im_end|>`, `<tool_call>` ...), moderately after the words `user` /
  `assistant`, weakly or more after an ordinary word, and near zero after a digit
  or a sentence-ending period (those are separate tokens, handled as 0).
Everything else is 0.
"""
READS = ()

TAGS = {"<|im_end|>", "<|im_start|>", "<tool_call>", "<tool_response>", "</tool_response>",
        "<think>", "</think>"}
ROLES = {"user", "assistant"}
OPENERS = {'"', "'", "“", "‘", "(", "[", "{", "/", "`", "$", "\\\""}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if prev.endswith(":"):
        if tok.strip() == "":
            return carry, 1.5
        if tok.strip(" ") in OPENERS:
            return carry, 1.0 if prev.endswith('":') else 0.5
    if tok == " " and prev.endswith("="):
        return carry, 0.2
    if tok.strip() == "" and "\n" in tok:
        if prev in TAGS:
            return carry, -0.8
        if prev in ROLES:
            return carry, -0.45
        if prev[-1:].isalpha():
            return carry, -0.5 if tok[:1] == " " else -0.2
    return carry, 0.0

