"""Predict a negative boundary signal on standalone opening punctuation.
An unspaced '(' is strongest, particularly after identifier-like tokens;
common mathematical names weaken it, dot-prefixed words strengthen it.
Its magnitude also decreases slowly with document position. Other bare
brackets, underscores, quotes and backslashes receive smaller responses,
conditioned on the preceding token's final character. Punctuation fused with
spaces or other punctuation is handled separately; everything else is zero.
All tests use punctuation, character classes and named math words. Context
resets at each document boundary.
"""
import math
import re

READS = ()
MATH_WORDS = {
    "sqrt", "sin", "cos", "tan", "log", "ln", "exp", "arcsin", "arccos",
    "arctan", "sinh", "cosh", "tanh", "det", "lim", "min", "max", "gcd",
    "left", "right", "frac",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        previous, position = carry[1], carry[2] + 1
    last = previous[-1:]
    word = bool(last and last.isalpha())
    number = bool(last and last.isdigit())
    space = bool(previous and previous.isspace())
    attached = word or number
    value = 0.0

    if token == '(':
        value = -2.07
        if word:
            letters = re.search(r"([^\W\d_]+)$", previous)[0]
            value -= 1.12 + 0.056 * min(len(letters), 10)
            if letters.lower() in MATH_WORDS:
                value += 0.82
            if previous.lstrip().startswith('.'):
                value -= 0.38
        elif number:
            value -= 0.95
        elif space:
            value -= 0.22
        if position:
            value += 0.112 * math.log1p(position)
        else:
            value = -4.62
    elif token.startswith('(') and not token[1:].strip():
        value = -1.33 if attached else -0.64 if space else -0.42
    elif token == '[':
        value = -1.75 if attached else -0.98 if space else -0.73
        if not position:
            value = -2.76
    elif token == '{':
        value = -0.61 if attached else -0.36 if space else -0.23
    elif token == '（':
        value = -1.18 if attached else -0.86
    elif token == '<':
        value = -0.85 if word else -0.73 if number else -0.42
    elif token == '_':
        value = -0.56 if word else -0.51 if number else -0.44 if space else -0.18
    elif token == '\\':
        value = -0.39 if attached else -0.15 if space else -0.05
    elif token in ('"', "'", '“'):
        value = (-0.12 if word else -0.13 if number else -0.40) if token == '"' else 0.0
        if token == "'" and not attached:
            value = -0.30
        if token == '“':
            value = -0.15 if attached else -0.35
        if previous.endswith('(f') or previous.strip() == 'f':
            value = -0.75 if token == '"' else -0.62
        if not position:
            value = 0.15
    elif token in ('("', "('", '({', '(['):
        value = -0.32 if attached else 0.0
    elif token == '(\\':
        value = -1.03
    elif token in ('(-', '(*', '($', '(_', '(!', '!(', '}(', '>(', '__('):
        value = -0.50
    elif token in ('\\[', '[\\', '[-'):
        value = -0.38
    elif token in ('\\"', '",', "',", '{\\'):
        value = -0.12
    elif token in ('__', '}{', '}_{'):
        value = 0.15 if token == '__' else 0.28
    elif token.startswith(' (') and token[2:] and not any(c.isalnum() for c in token):
        tail = token[2:]
        if not tail.strip():
            value = 0.05
        elif tail == '\\':
            value = 0.0
        elif tail == '-':
            value = 0.20
        else:
            value = 0.5

    return (doc, token, position), float(value)

